/* generado por prompts/herramientas/clave-tests.js; no editar a mano */
(window.CLAVE_TEST=window.CLAVE_TEST||{})[2]=[{"a":"Artículo 8 — Infracciones","q":[{"i":"2-ia-1813","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Infracciones graves. Constituye infracción grave el establecimiento o mantenimiento de relaciones de negocio o la ejecución de operaciones:","o":["prohibidas.","sin identificar al titular real.","con personas con responsabilidad pública.","con países con deficiencias estratégicas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">prohibidas</mark></span>El <span class=\"ref-norma\">art. 52.1.x de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"El establecimiento o mantenimiento de relaciones de negocio o la ejecución de operaciones prohibidas\"</span>. La conducta es mantener relaciones o ejecutar operaciones prohibidas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1035","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Infracciones. Constituirán infracciones muy graves. Señale la INCORRECTA:","o":["La realización de operaciones prohibidas en virtud de las medidas de salvaguardia o excepcionales.","La realización de operaciones sin solicitar autorización cuando sea preceptiva.","La falta de declaración de operaciones cuya cuantía supere los 6.000.000 de euros.","La falta de veracidad en las solicitudes de autorización, si puede estimarse especialmente relevante."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La falta de declaración de operaciones cuya cuantía supere los 6.000.000 de euros</mark></span>El <span class=\"ref-norma\">art. 8.2 y 8.3 de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"La falta de declaración de operaciones cuya cuantía supere los 6.000.000 de euros\"</span>. Esa conducta es infracción GRAVE; las otras tres son infracciones muy graves. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1036","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Infracciones. Constituirá infracción muy grave la falta de veracidad en las solicitudes de autorización presentadas ante los organismos competentes, siempre que:","o":["se haya cometido de forma reiterada.","pueda estimarse como especialmente relevante.","la operación supere los 6.000.000 de euros, sin perjuicio de lo dispuesto en otras disposiciones.","se hubiese producido con ánimo de lucro."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">pueda estimarse como especialmente relevante</mark></span>El <span class=\"ref-norma\">art. 8.2.c de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"La falta de veracidad en las solicitudes de autorización presentadas ante los organismos competentes, siempre que pueda estimarse como especialmente relevante\"</span>. El requisito es que la falta de veracidad pueda estimarse como especialmente relevante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-203","p":"Convenio del Consejo de Europa para la prevención del terrorismo. Delitos accesorios. Cada Parte tipificará como delito la contribución a la comisión de delitos previstos en los artículos 5 a 7 por un grupo de personas que actúe con un objetivo común. Esta contribución deberá ser deliberada y tener como objetivo facilitar la actividad criminal del grupo o efectuarse:","o":["Con conocimiento de que al menos uno de sus miembros ha sido condenado anteriormente por delitos de terrorismo.","Sabiendo que el grupo tiene intención de cometer un delito previsto en los artículos 5 a 7.","Con la autorización previa y por escrito de la autoridad competente del Estado de la Parte interesada.","Con ánimo de lucro y de forma habitual durante un período ininterrumpido no inferior a un año."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Sabiendo que el grupo tiene intención de cometer un delito previsto en los artículos 5 a 7</mark></span>Según el <span class=\"ref-norma\">art. 9.1 c) del Convenio n.º 196 del Consejo de Europa</span>: <span class=\"ref-concepto\">\"efectuarla sabiendo que el grupo tiene intención de cometer un delito previsto en los artículos 5 a 7\"</span>. Los dos supuestos alternativos: facilitar la actividad criminal del grupo o actuar sabiendo la intención del grupo. <i>(marca EXOF del temario)</i>"},{"i":"2-1","p":"Ley 19/2003, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Régimen sancionador. Constituirán infracciones graves:","o":["Las declaraciones realizadas por los sujetos obligados fuera de los plazos reglamentariamente establecidos.","La falta de declaración de operaciones cuya cuantía no supere 6.000.000 de euros, así como la falta de veracidad u omisión o inexactitud en los datos de las declaraciones que no superen dicha cuantía.","La falta de veracidad en las solicitudes de autorización presentadas ante los organismos competentes, siempre que pueda estimarse como especialmente relevante.","La falta de declaración de operaciones cuya cuantía supere los 6.000.000 de euros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La falta de declaración de operaciones cuya cuantía supere los 6.000.000 de euros.</mark></span><span class=\"ref-norma\">Art. 8.3.a) · Ley 19/2003</span>. Según el art. 8.3.a) de la Ley 19/2003, constituye infracción GRAVE \"la falta de declaración de operaciones cuya cuantía supere los 6.000.000 de euros\" (opción D). La opción B, en cambio, describe una infracción LEVE (art. 8.4.b), y la opción C describe una infracción MUY GRAVE (art. 8.2.c)."},{"i":"2-72","p":"Ley 19/2003, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Régimen sancionador. Constituirán infracciones graves:","o":["Las declaraciones realizadas por los sujetos obligados fuera de los plazos reglamentariamente establecidos.","La falta de declaración de operaciones cuya cuantía no supere 6.000.000 de euros, así como la falta de veracidad u omisión o inexactitud en los datos de las declaraciones que no superen dicha cuantía.","La falta de veracidad en las solicitudes de autorización presentadas ante los organismos competentes, siempre que pueda estimarse como especialmente relevante.","La falta de declaración de operaciones cuya cuantía supere los 6.000.000 de euros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La falta de declaración de operaciones cuya cuantía supere los 6.000.000 de euros.</mark></span><span class=\"ref-norma\">Art. 8.3.a) · Ley 19/2003</span>. El artículo 8.3.a) de la Ley 19/2003 dispone que constituye infracción grave \"la falta de declaración de operaciones cuya cuantía supere los 6.000.000 de euros\"; la falta de declaración de operaciones que NO superen esa cuantía es infracción leve (art. 8.4.b)."},{"i":"2-ia-1038","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Infracciones. Constituye infracción grave la falta de veracidad, la omisión o inexactitud en los datos de las declaraciones respecto de operaciones cuya cuantía:","o":["supere los 600.000 euros.","alcance los 3.000.000 de euros.","exceda de 30.000 euros.","supere los 6.000.000 de euros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">supere los 6.000.000 de euros</mark></span>El <span class=\"ref-norma\">art. 8.3.b de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"La falta de veracidad, la omisión o inexactitud en los datos de las declaraciones respecto de operaciones cuya cuantía supere los 6.000.000 de euros\"</span>. El umbral de las infracciones graves es superar los 6.000.000 de euros; por debajo la conducta es leve. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1040","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Infracciones. Constituye infracción leve la falta de declaración de operaciones cuya cuantía no supere:","o":["600.000 euros, sin perjuicio de lo dispuesto en otras disposiciones.","6.000.000 de euros.","60.000 euros.","6.000 euros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">6.000.000 de euros</mark></span>El <span class=\"ref-norma\">art. 8.4.b de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"La falta de declaración de operaciones cuya cuantía no supere 6.000.000 de euros\"</span>. La falta de declaración es leve si no supera 6.000.000 de euros; si lo supera, es grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1037","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Infracciones. Constituyen infracciones graves los incumplimientos de los requerimientos efectuados por los organismos competentes en el cumplimiento de sus funciones, cuando se hayan efectuado:","o":["de modo expreso y por escrito.","por escrito y con acuse de recibo.","de modo expreso y con carácter previo.","por cualquier medio que deje constancia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de modo expreso y por escrito</mark></span>El <span class=\"ref-norma\">art. 8.3.c de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"Los incumplimientos de los requerimientos efectuados, de modo expreso y por escrito, por los organismos competentes en el cumplimiento de sus funciones\"</span>. Los requerimientos han de ser expresos y por escrito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1039","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Infracciones. Constituirán infracciones leves las declaraciones realizadas por los sujetos obligados:","o":["sin la información estadística requerida.","con datos inexactos que no superen los 6.000 euros.","fuera de los plazos reglamentariamente establecidos.","sin el soporte documental reglamentariamente exigido."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">fuera de los plazos reglamentariamente establecidos</mark></span>El <span class=\"ref-norma\">art. 8.4.a de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"Las declaraciones realizadas por los sujetos obligados fuera de los plazos reglamentariamente establecidos\"</span>. Es infracción leve la declaración fuera de los plazos reglamentarios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 9 y 10 — Sanciones y graduación ✱ R2","q":[{"i":"2-ia-1041","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Sanciones. Por la comisión de infracciones muy graves se impondrán simultáneamente una multa y amonestación pública o privada. La multa podrá ascender hasta el tanto del contenido económico de la operación, sin que pueda ser inferior a:","o":["30.000 euros.","6.000 euros.","3.000 euros.","60.000 euros, en los términos que establezca la propia norma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">30.000 euros</mark></span>El <span class=\"ref-norma\">art. 9.2.a de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"Multa, que podrá ascender hasta el tanto del contenido económico de la operación sin que pueda ser inferior a 30.000 euros\"</span>. Muy graves: hasta el tanto del contenido económico y mínimo de 30.000 euros; graves: 6.000 euros; leves: 3.000 euros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1117","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Disposición adicional primera. Modificación de la Ley 19/1993, de 28 de diciembre, sobre determinadas medidas de prevención del blanqueo de capitales. Si los medios de pago fueran hallados en lugar o situación que mostrase una clara intención de ocultarlos, o no resulta debidamente acreditado el origen de los fondos, la sanción podrá llegar:","o":["al tanto del contenido económico de los medios empleados.","al doble del contenido económico de los medios empleados.","a la mitad del contenido económico de los medios empleados.","a 6.000 euros por cada medio de pago empleado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al tanto del contenido económico de los medios empleados</mark></span>El <span class=\"ref-norma\">disposición adicional primera (art. 8.3 de la Ley 19/1993) de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"la sanción podrá llegar al tanto del contenido económico de los medios empleados\"</span>. Ocultación o falta de acreditación del origen elevan el máximo al tanto del contenido económico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-200","p":"Ley 19/2003, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Sanciones. Por la comisión de infracciones muy graves se impondrán simultáneamente una multa, que podrá ascender hasta el tanto del contenido económico de la operación sin que pueda ser inferior a 30.000 euros, y:","o":["Amonestación pública o privada.","Amonestación privada exclusivamente.","Suspensión temporal de la actividad por un máximo de seis meses.","Inhabilitación para ejercer cargos de administración durante diez años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Amonestación pública o privada</mark></span>Según el <span class=\"ref-norma\">art. 9.2 de la Ley 19/2003</span>: <span class=\"ref-concepto\">\"sin que pueda ser inferior a 30.000 euros, y b) amonestación pública o privada\"</span>. Graves: multa de hasta la mitad del contenido económico (mínimo 6.000 euros); leves: hasta un cuarto (mínimo 3.000 euros) y solo amonestación privada. <i>(marca EXOF del temario)</i>"},{"i":"2-ia-1042","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Sanciones. Por la comisión de infracciones graves la multa podrá ascender hasta __________ del contenido económico de la operación, sin que pueda ser inferior a 6.000 euros.","o":["el tanto","un cuarto","un tercio","la mitad"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la mitad</mark></span>El <span class=\"ref-norma\">art. 9.3.a de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"Multa, que podrá ascender hasta la mitad del contenido económico de la operación sin que pueda ser inferior a 6.000 euros\"</span>. Graves: hasta la mitad; muy graves: hasta el tanto; leves: hasta un cuarto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1043","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Sanciones. Por la comisión de infracciones leves se impondrá una multa, que podrá ascender hasta un cuarto del contenido económico de la operación sin que pueda ser inferior a 3.000 euros, y amonestación:","o":["pública.","pública o privada.","privada.","pública, con publicación en el Boletín Oficial del Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">privada</mark></span>El <span class=\"ref-norma\">art. 9.4 de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"a) Multa, que podrá ascender hasta un cuarto del contenido económico de la operación sin que pueda ser inferior a 3.000 euros, y b) Amonestación privada\"</span>. En las leves la amonestación es solo privada; en las graves y muy graves, pública o privada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1045","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Sanciones. En la presentación fuera de plazo de las declaraciones, sin actuación o requerimiento previo de la Administración, si han transcurrido más de seis meses se impondrá una multa de hasta:","o":["600 euros, sin que pueda ser inferior a 300 euros.","600 euros, sin que pueda ser inferior a 150 euros, en los términos que establezca la propia norma.","300 euros, sin que pueda ser inferior a 150 euros.","900 euros, sin que pueda ser inferior a 450 euros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">600 euros, sin que pueda ser inferior a 300 euros</mark></span>El <span class=\"ref-norma\">art. 9.5.b de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"Si han transcurrido más de seis meses, hasta 600 euros, sin que pueda ser inferior a 300 euros\"</span>. Pasados más de seis meses: hasta 600 euros y mínimo de 300 euros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-120","p":"Ley 19/2003, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Régimen sancionador. Cuando la infracción consista en la presentación fuera de plazo de las declaraciones por los sujetos obligados, sin actuación o requerimiento previo de la Administración, se impondrán las siguientes sanciones:","o":["Si no han transcurrido más de tres meses, hasta 300 euros, sin que pueda ser inferior a 150 euros; si han transcurrido más de tres meses, hasta 600 euros, sin que pueda ser inferior a 300 euros.","Si no han transcurrido más de seis meses, hasta 600 euros, sin que pueda ser inferior a 300 euros; si han transcurrido más de seis meses, hasta 3.000 euros, sin que pueda ser inferior a 600.","Si no han transcurrido más de seis meses, hasta 300 euros, sin que pueda ser inferior a 150 euros; si han transcurrido más de seis meses, hasta 600 euros, sin que pueda ser inferior a 300 euros.","Si no han transcurrido más de seis meses, amonestación privada; si han transcurrido más de seis meses, multa de hasta 600 euros, sin que pueda ser inferior a 300 euros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Si no han transcurrido más de seis meses, hasta 300 euros, sin que pueda ser inferior a 150 euros; si han transcurrido más de seis meses, hasta 600 euros, sin que pueda ser inferior a 300 euros</mark></span>Según el <span class=\"ref-norma\">Ley 19/2003, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior</span>: <span class=\"ref-concepto\">\"si no han transcurrido más de seis meses, hasta 300 euros, sin que pueda ser inferior a 150 euros\"</span>. Ficha RECUERDA R2. <i>(ficha RECUERDA R2 del temario)</i>"},{"i":"2-ia-1044","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Sanciones. Cuando la infracción consista en la presentación fuera de plazo de las declaraciones por los sujetos obligados, sin actuación o requerimiento previo de la Administración, si no han transcurrido más de seis meses se impondrá una multa de hasta:","o":["150 euros, sin que pueda ser inferior a 75 euros.","300 euros, sin que pueda ser inferior a 150 euros.","600 euros, sin que pueda ser inferior a 300 euros, sin perjuicio de lo dispuesto en otras disposiciones.","300 euros, sin que pueda ser inferior a 100 euros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">300 euros, sin que pueda ser inferior a 150 euros</mark></span>El <span class=\"ref-norma\">art. 9.5.a de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"Si no han transcurrido más de seis meses, hasta 300 euros, sin que pueda ser inferior a 150\"</span>. Hasta seis meses de retraso: hasta 300 euros, mínimo 150 euros; pasados los seis meses: hasta 600 euros, mínimo 300 euros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1123","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Disposición adicional primera. Modificación de la Ley 19/1993, de 28 de diciembre, sobre determinadas medidas de prevención del blanqueo de capitales. Todas las fundaciones conservarán durante __________ años registros con las identidades de todas las personas que reciban fondos o recursos de la fundación, que estarán a disposición del Protectorado, de la Comisión de Vigilancia de Actividades de Financiación del Terrorismo y de los órganos administrativos o judiciales competentes.","o":["cinco","diez","seis","tres"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">seis</mark></span>El <span class=\"ref-norma\">disposición adicional primera (disposición adicional segunda de la Ley 19/1993) de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"todas las fundaciones conservarán durante seis años registros con las identidades de todas las personas que reciban fondos o recursos de la fundación\"</span>. El plazo de conservación de los registros es de seis años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2316","p":"Protocolo para prevenir, reprimir y sancionar la trata de personas, especialmente mujeres y niños, que complementa la Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Solución de controversias. Toda controversia entre dos o más Estados Parte sobre la interpretación o aplicación del Protocolo que no pueda resolverse mediante la negociación dentro de un plazo razonable deberá, a solicitud de uno de ellos, someterse a arbitraje. Si, transcurrido un plazo desde la solicitud de arbitraje, no han podido ponerse de acuerdo sobre su organización, cualquiera de ellos podrá remitir la controversia a la Corte Internacional de Justicia. Ese plazo es de:","o":["tres meses, sin perjuicio de lo dispuesto en otras disposiciones.","seis meses.","un año.","dos meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">seis meses</mark></span>El <span class=\"ref-norma\">art. 15.2 de el Protocolo contra la trata de personas</span> dispone: <span class=\"ref-concepto\">\"Si, seis meses después de la fecha de la solicitud de arbitraje, esos Estados Parte no han podido ponerse de acuerdo sobre la organización del arbitraje\"</span>. El plazo es de seis meses desde la solicitud de arbitraje. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-22","p":"Ley 19/2003, de 4 de julio, sobre el Régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Las sanciones aplicables en cada caso por la comisión de infracciones muy graves, graves o leves se determinarán considerándose las siguientes circunstancias: Señale la incorrecta.","o":["El tiempo transcurrido entre la comisión de la infracción y su descubrimiento por la Administración.","La conducta anterior del infractor en relación con las normas en materia de movimientos de capitales y pagos exteriores, tomando en consideración al efecto las sanciones firmes que le hubieran sido impuestas durante los últimos cinco años.","La naturaleza y entidad de la infracción.","El grado de responsabilidad e intencionalidad en los hechos que concurran en el interesado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El tiempo transcurrido entre la comisión de la infracción y su descubrimiento por la Administración</mark></span>Es la incorrecta porque el art. 10.c) habla del tiempo entre la comisión de la infracción y el intento de SUBSANACIÓN, no de su descubrimiento; la opción B (ahora con «cinco años») sí es un criterio legal. Según el <span class=\"ref-norma\">art. 10 de la Ley 19/2003</span>: <span class=\"ref-concepto\">\"La conducta anterior del interesado, en relación con las normas en materia de movimientos de capitales y pagos exteriores, tomando en consideración al efecto las sanciones firmes que le hubieran sido impuestas durante los últimos cinco años\"</span> (verificado con el texto del temario oficial)."},{"i":"2-ia-1047","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Graduación de sanciones. Entre las circunstancias para graduar las sanciones figura el tiempo que haya mediado entre la comisión de la infracción y el intento de subsanación de ésta, que ha de producirse:","o":["de oficio por la Administración.","a requerimiento del órgano instructor.","por iniciativa propia del interesado.","antes del inicio del procedimiento sancionador."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por iniciativa propia del interesado</mark></span>El <span class=\"ref-norma\">art. 10.c de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"El tiempo que haya mediado entre la comisión de la infracción y el intento de subsanación de ésta por iniciativa propia del interesado\"</span>. La subsanación relevante es la intentada por iniciativa propia del interesado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1048","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Graduación de sanciones. Para graduar las sanciones se consideran la naturaleza y entidad de la infracción, el grado de responsabilidad e intencionalidad, el tiempo mediado hasta el intento de subsanación, la capacidad económica del interesado y:","o":["la reincidencia del interesado en cualquier infracción administrativa de naturaleza económica, sin perjuicio de lo dispuesto en otras disposiciones.","la conducta anterior del interesado en relación con las normas de movimientos de capitales y pagos exteriores.","el beneficio económico obtenido por el interesado con la realización de la operación.","el perjuicio causado a la Hacienda Pública y a la estabilidad del sistema financiero."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la conducta anterior del interesado en relación con las normas de movimientos de capitales y pagos exteriores</mark></span>El <span class=\"ref-norma\">art. 10 de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"La conducta anterior del interesado, en relación con las normas en materia de movimientos de capitales y pagos exteriores\"</span>. La quinta circunstancia es la conducta anterior en relación con las normas de movimientos de capitales y pagos exteriores; no se citan beneficio obtenido ni perjuicio causado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 5, 6 y 7 — Provocación pública, reclutamiento y adiestramiento con fines terroristas ✱ R5","q":[{"i":"2-ia-1208","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Delitos accesorios. Cada Parte adoptará las medidas necesarias para que se califique como delito la tentativa de cometer un delito de reclutamiento o de adiestramiento con fines terroristas. La tentativa NO está prevista como delito en el caso de:","o":["el reclutamiento con fines terroristas.","la provocación pública para cometer delitos terroristas.","el adiestramiento con fines terroristas.","el reclutamiento y el adiestramiento con fines terroristas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la provocación pública para cometer delitos terroristas</mark></span>El <span class=\"ref-norma\">art. 9.2 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"la tentativa de cometer un delito de los previstos en los artículos 6 y 7 del presente Convenio\"</span>. La tentativa se tipifica solo para el reclutamiento y el adiestramiento, no para la provocación pública. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-6","p":"Convenio del Consejo de Europa para la prevención del terrorismo. A los efectos del presente Convenio, se entenderá por “provocación pública para cometer delitos terroristas”:","o":["El hecho de incitar a otra persona a cometer o participar en la comisión de delitos terroristas, o a unirse a una asociación o a un grupo para contribuir a que éstos cometan uno o varios delitos terroristas.","El hecho de dar instrucciones para la fabricación o el uso de explosivos, armas de fuego u otras armas o sustancias nocivas o peligrosas, o para otros métodos y técnicas específicos con vistas a cometer delitos terroristas o a contribuir a su comisión, sabiendo que la información facilitada tiene por objeto dar el uso a la fabricación o a tales objetivos.","La difusión o cualquier otra forma de puesta a disposición del público de mensajes con la intención de incitar a cometer delitos terroristas, cuando ese comportamiento, ya preconice directamente o no la comisión de delitos terroristas, cree peligros de que se puedan cometer uno o varios delitos.","Todos son correctos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La difusión o cualquier otra forma de puesta a disposición del público de mensajes con la intención de incitar a cometer delitos terroristas, cuando ese comportamiento, ya preconice directamente o no la comisión de delitos terroristas, cree peligros de que se puedan cometer uno o varios delitos.</mark></span><span class=\"ref-norma\">Art. 5.1 · Convenio del Consejo de Europa para la prevención del terrorismo</span>. La respuesta correcta es la C porque el artículo 5.1 del Convenio del Consejo de Europa para la prevención del terrorismo define la «provocación pública para cometer delitos terroristas» como «la difusión o cualquier otra forma de puesta a disposición del público de mensajes con la intención de incitar a cometer delitos terroristas, cuando ese comportamiento, ya preconice directamente o no la comisión de delitos terroristas, cree peligro de que se puedan cometer uno o varios delitos»."},{"i":"2-77","p":"Convenio del Consejo de Europa para la prevención del terrorismo. A los efectos del presente Convenio, se entenderá por «provocación pública para cometer delitos terroristas»:","o":["El hecho de incitar a otra persona a cometer o participar en la comisión de delitos terroristas, o a unirse a una asociación o a un grupo para contribuir a que éstos cometan uno o varios delitos terroristas.","El hecho de dar instrucciones para la fabricación o el uso de explosivos, armas de fuego u otras armas o sustancias nocivas o peligrosas, o para otros métodos y técnicas específicos con vistas a cometer delitos terroristas o a contribuir a su comisión, sabiendo que la información facilitada tiene por objeto dar el uso a la fabricación o a tales objetivos.","La difusión o cualquier otra forma de puesta a disposición del público de mensajes con la intención de incitar a cometer delitos terroristas, cuando ese comportamiento, ya preconice directamente o no la comisión de delitos terroristas, cree peligros de que se puedan cometer uno o varios delitos.","Todos son correctos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">DIFUSIÓN DE MENSAJES CON LA INTENCIÓN DE INCITAR A COMETER DELITOS TERRORISTAS, CREANDO PELIGRO DE QUE SE COMETAN.</mark></span><span class=\"ref-norma\">Art. 5 · Convenio del Consejo de Europa para la prevención del terrorismo</span>. El art. 5 del Convenio define la provocación pública como la difusión o puesta a disposición del público de mensajes con intención de incitar a cometer delitos terroristas, cuando dicha conducta cree peligro de que se cometan uno o varios de esos delitos. Las opciones A y B corresponden, respectivamente, a las definiciones de reclutamiento (art. 6) y adiestramiento (art. 7) con fines terroristas."},{"i":"2-ia-1201","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Provocación pública para cometer delitos terroristas. Se entenderá por «provocación pública para cometer delitos terroristas» la difusión o cualquier otra forma de puesta a disposición del público de mensajes con la intención de incitar a cometer delitos terroristas, cuando ese comportamiento, ya preconice directamente o no la comisión de delitos terroristas:","o":["cree peligro de que se puedan cometer uno o varios delitos.","ponga en riesgo la seguridad del Estado destinatario del mensaje.","se realice a través de medios de comunicación de gran difusión.","provoque de forma efectiva la comisión de un delito terrorista."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cree peligro de que se puedan cometer uno o varios delitos</mark></span>El <span class=\"ref-norma\">art. 5.1 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"cuando ese comportamiento, ya preconice directamente o no la comisión de delitos terroristas, cree peligro de que se puedan cometer uno o varios delitos\"</span>. Basta con que el comportamiento cree peligro de que se cometan delitos, aunque no los preconice directamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-79","p":"Convenio del Consejo de Europa para la prevención del terrorismo. Cada Parte adoptará las medidas necesarias para tipificar como delito, de conformidad con su derecho interno, el reclutamiento con fines terroristas cuando se cometa:","o":["Intencionada y objetivamente.","Ilegal e intencionadamente.","Objetiva e ilegalmente.","Objetiva y dolosamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">ILEGAL E INTENCIONADAMENTE.</mark></span><span class=\"ref-norma\">Art. 6.2 · Convenio del Consejo de Europa para la prevención del terrorismo</span>. El art. 6.2 del Convenio exige tipificar el reclutamiento con fines terroristas cuando se cometa ilegal e intencionadamente, en los mismos términos que la provocación pública (art. 5.2) y el adiestramiento (art. 7.2)."},{"i":"2-ia-1202","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Provocación pública para cometer delitos terroristas. Cada Parte adoptará las medidas necesarias para tipificar como delito, de conformidad con su derecho interno, la provocación pública para cometer delitos terroristas cuando se cometa:","o":["ilegalmente y con ánimo de lucro.","de forma intencionada y reiterada.","ilegalmente y a través de medios electrónicos.","ilegal e intencionadamente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ilegal e intencionadamente</mark></span>El <span class=\"ref-norma\">art. 5.2 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"la provocación pública para cometer delitos terroristas tal como se define en el apartado 1, cuando se cometa ilegal e intencionadamente\"</span>. El requisito es que se cometa ilegal e intencionadamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1144","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Políticas nacionales de prevención. Cada Parte promoverá la tolerancia fomentando el diálogo interreligioso y transcultural y, en su caso, la participación de organizaciones no gubernamentales y otros actores de la sociedad civil, con objeto de:","o":["prevenir la radicalización violenta de los jóvenes y de las minorías.","prevenir tensiones que podrían contribuir a la comisión de delitos terroristas.","fomentar la integración de las comunidades extranjeras en la sociedad de acogida.","sensibilizar al público sobre la amenaza que suponen los delitos terroristas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">prevenir tensiones que podrían contribuir a la comisión de delitos terroristas</mark></span>El <span class=\"ref-norma\">art. 3.3 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"con objeto de prevenir tensiones que podrían contribuir a la comisión de delitos terroristas\"</span>. La finalidad es prevenir tensiones que podrían contribuir a la comisión de delitos terroristas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1203","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Reclutamiento con fines terroristas. Se entenderá por «reclutamiento con fines terroristas» el hecho de incitar a otra persona a cometer o participar en la comisión de delitos terroristas, o a:","o":["financiar a una asociación o a un grupo para que éstos cometan uno o varios delitos terroristas, conforme al procedimiento que se establezca reglamentariamente.","viajar a otro Estado para recibir adiestramiento con fines terroristas.","unirse a una asociación o a un grupo para contribuir a que éstos cometan uno o varios delitos terroristas.","prestar apoyo logístico a una organización que cometa delitos terroristas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">unirse a una asociación o a un grupo para contribuir a que éstos cometan uno o varios delitos terroristas</mark></span>El <span class=\"ref-norma\">art. 6.1 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"o a unirse a una asociación o a un grupo para contribuir a que éstos cometan uno o varios delitos terroristas\"</span>. El reclutamiento incluye incitar a unirse a una asociación o a un grupo para contribuir a sus delitos terroristas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1446","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Aplicación por terceros de las medidas de diligencia debida. Los sujetos obligados podrán recurrir a terceros sometidos a la Ley para la aplicación de las medidas de diligencia debida, con excepción del seguimiento continuo de la relación de negocios. Esta limitación no será aplicable:","o":["a los terceros de otros Estados miembros.","a las organizaciones o federaciones de sujetos obligados.","a las relaciones de externalización o agencia.","en el caso de grupos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en el caso de grupos</mark></span>El <span class=\"ref-norma\">art. 8.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"con excepción del seguimiento continuo de la relación de negocios regulada en el artículo 6. Esta limitación no será aplicable en el caso de grupos\"</span>. En los grupos el seguimiento continuo también puede encomendarse a un tercero. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-8","p":"Convenio del Consejo de Europa para la prevención del terrorismo. Cada Parte adoptará las medidas necesarias para tipificar como delito, de conformidad con su derecho interno, el reclutamiento con fines terroristas cuando se cometa:","o":["Intencionada y objetivamente.","Ilegal e intencionadamente.","Objetiva e ilegalmente.","Objetiva y dolosamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Ilegal e intencionadamente.</mark></span><span class=\"ref-norma\">Art. 6.2 · Convenio del Consejo de Europa para la prevención del terrorismo</span>. La respuesta correcta es la B porque el artículo 6.2 del Convenio del Consejo de Europa para la prevención del terrorismo establece que cada Parte adoptará las medidas necesarias para tipificar como delito el reclutamiento con fines terroristas, tal como se define en el apartado 1, «cuando se cometa ilegal e intencionadamente»."},{"i":"2-ia-1204","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Adiestramiento con fines terroristas. Se entenderá por «adiestramiento con fines terroristas» el hecho de dar instrucciones para la fabricación o el uso de explosivos, armas de fuego u otras armas o sustancias nocivas o peligrosas, o para otros métodos y técnicas específicos con vistas a cometer delitos terroristas o a contribuir a su comisión, sabiendo que:","o":["los receptores de la formación pertenecen a una organización terrorista.","la formación facilitada tiene por objeto servir para la realización de tales objetivos.","la formación se facilita en el territorio de un Estado distinto del de los receptores, sin perjuicio de lo dispuesto en otras disposiciones.","los instruidos han sido previamente reclutados con fines terroristas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la formación facilitada tiene por objeto servir para la realización de tales objetivos</mark></span>El <span class=\"ref-norma\">art. 7.1 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"sabiendo que la formación facilitada tiene por objeto servir para la realización de tales objetivos\"</span>. El elemento subjetivo es saber que la formación facilitada servirá para la realización de tales objetivos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"RESERVA DE NO APLICAR LA CLÁUSULA DE EXCEPCIÓN POLÍTICA art. 20.5 y 20.6 · cuadro del temario","q":[{"i":"2-15","p":"Convenio del Consejo de Europa para la prevención del terrorismo. Exclusión de la cláusula de excepción política. Cualquiera de las Partes podrá retirar, total o parcialmente, una reserva de no aplicar la cláusula de excepción política, por medio de una declaración dirigida:","o":["A la Asamblea General del Consejo de Europa, que entrará en vigor tres meses después de la fecha de su recepción.","Al Secretario General del Consejo de Europa, que entrará en vigor en la fecha de su recepción.","A la Asamblea General del Consejo de Europa, que entrará en vigor en la fecha de su recepción.","Al Secretario General del Consejo de Europa, que entrará en vigor tres meses después de la fecha de su recepción."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al Secretario General del Consejo de Europa, que entrará en vigor en la fecha de su recepción.</mark></span><span class=\"ref-norma\">Art. 20.3 · Convenio del Consejo de Europa para la prevención del terrorismo</span>. La respuesta correcta es la B porque el artículo 20.3 del Convenio del Consejo de Europa para la prevención del terrorismo establece que cualquiera de las Partes podrá retirar, total o parcialmente, la reserva de no aplicar la cláusula de excepción política «por medio de una declaración dirigida al Secretario General del Consejo de Europa, que entrará en vigor en la fecha de su recepción»."},{"i":"2-85","p":"Convenio del Consejo de Europa para la prevención del terrorismo. Exclusión de la cláusula de excepción política. Cualquiera de las Partes podrá retirar, total o parcialmente, una reserva de no aplicar la cláusula de excepción política, por medio de una declaración dirigida:","o":["A la Asamblea General del Consejo de Europa, que entrará en vigor tres meses después de la fecha de su recepción.","Al Secretario General del Consejo de Europa, que entrará en vigor en la fecha de su recepción.","A la Asamblea General del Consejo de Europa, que entrará en vigor en la fecha de su recepción.","Al Secretario General del Consejo de Europa, que entrará en vigor tres meses después de la fecha de su recepción."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">AL SECRETARIO GENERAL DEL CONSEJO DE EUROPA, QUE ENTRARÁ EN VIGOR EN LA FECHA DE SU RECEPCIÓN.</mark></span><span class=\"ref-norma\">Art. 20.3 · Convenio del Consejo de Europa para la prevención del terrorismo</span>. El art. 20.3 del Convenio establece que la retirada de la reserva se dirigirá al Secretario General del Consejo de Europa y entrará en vigor en la fecha de su recepción."},{"i":"2-159","p":"Convenio del Consejo de Europa para la prevención del terrorismo. Exclusión de la cláusula de excepción política. La Parte que se reserve el derecho de no aplicar el apartado 1 del artículo 20 (exclusión de la cláusula de excepción política) a la extradición se compromete a aplicar esta reserva:","o":["Caso por caso, sobre la base de una decisión debidamente motivada.","De forma general y automática, sin necesidad de motivar cada decisión de extradición.","Únicamente previa autorización expresa del Comité de Ministros del Consejo de Europa.","Solo respecto de los delitos cometidos en su propio territorio, previa consulta a las demás Partes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Caso por caso, sobre la base de una decisión debidamente motivada</mark></span>Según el <span class=\"ref-norma\">art. 20.2 del Convenio n.º 196 del Consejo de Europa</span>: <span class=\"ref-concepto\">\"La Parte se compromete a aplicar esta reserva caso por caso, sobre la base de una decisión debidamente motivada\"</span>. La reserva se aplica caso por caso, con decisión debidamente motivada. <i>(marca EXOF del temario)</i>"},{"i":"2-160","p":"Convenio del Consejo de Europa para la prevención del terrorismo. Exclusión de la cláusula de excepción política. Tres meses antes de la fecha de expiración de la reserva a la exclusión de la cláusula de excepción política, la Parte deberá notificar al Secretario General del Consejo de Europa:","o":["Su decisión definitiva de renovarla automáticamente por un nuevo período de cinco años.","La lista de las personas cuya extradición haya denegado durante la vigencia de la reserva.","El texto de las enmiendas que propone al artículo 20 del Convenio para suprimir la reserva.","Su intención de mantener, modificar o retirar la reserva."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Su intención de mantener, modificar o retirar la reserva</mark></span>Según el <span class=\"ref-norma\">art. 20.6 del Convenio n.º 196 del Consejo de Europa</span>: <span class=\"ref-concepto\">\"Tres meses antes de la fecha de expiración, la Parte deberá notificar al Secretario General su intención de mantener, modificar o retirar la reserva\"</span>. Doce meses antes informa el Secretario General; tres meses antes notifica la Parte su intención. <i>(marca EXOF del temario)</i>"},{"i":"2-161","p":"Convenio del Consejo de Europa para la prevención del terrorismo. Exclusión de la cláusula de excepción política. Si la Parte no notifica al Secretario General del Consejo de Europa su intención respecto de la reserva, este le informará de que su reserva queda automáticamente prorrogada por un período de:","o":["Un año.","Tres meses.","Seis meses.","Tres años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Seis meses</mark></span>Según el <span class=\"ref-norma\">art. 20.6 del Convenio n.º 196 del Consejo de Europa</span>: <span class=\"ref-concepto\">\"A falta de notificación por la Parte de que se trate, el Secretario General informará a dicha Parte de que su reserva queda automáticamente prorrogada por un período de seis meses\"</span>. Si tampoco notifica su decisión antes de expirar ese período, la reserva quedará sin efecto. <i>(marca EXOF del temario)</i>"},{"i":"2-ia-1234","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Exclusión de la cláusula de excepción política. Ninguno de los delitos mencionados en el Convenio se considerará, a efectos de los requisitos necesarios para la extradición o la asistencia judicial, como delito político o como delito conexo a un delito político, o como:","o":["un delito de opinión o de expresión.","un delito de resistencia contra un régimen opresor.","un delito cometido en un conflicto armado.","un delito inspirado por móviles políticos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un delito inspirado por móviles políticos</mark></span>El <span class=\"ref-norma\">art. 20.1 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"como delito político o como delito conexo a un delito político, o como un delito inspirado por móviles políticos\"</span>. La exclusión alcanza al delito político, al conexo y al inspirado por móviles políticos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1235","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Exclusión de la cláusula de excepción política. Cualquier Estado podrá declarar que se reserva el derecho de no aplicar la exclusión de la cláusula de excepción política a la extradición. Esa declaración debe efectuarse:","o":["en cualquier momento posterior a la entrada en vigor del Convenio para esa Parte, conforme al procedimiento que se establezca reglamentariamente.","en el plazo de un año desde la entrada en vigor del Convenio para esa Parte.","en el momento de la firma o del depósito de su instrumento de ratificación, aceptación, aprobación o adhesión.","en el momento de recibir la primera solicitud de extradición por esos delitos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en el momento de la firma o del depósito de su instrumento de ratificación, aceptación, aprobación o adhesión</mark></span>El <span class=\"ref-norma\">art. 20.2 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"podrán declarar, en el momento de la firma o del depósito de su instrumento de ratificación, aceptación, aprobación o adhesión al Convenio, que se reservan el derecho de no aplicar el apartado 1 de este artículo\"</span>. La reserva solo puede formularse al firmar o al depositar el instrumento de ratificación, aceptación, aprobación o adhesión; la Parte la aplicará caso por caso con decisión motivada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1236","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Exclusión de la cláusula de excepción política. Cualquiera de las Partes podrá retirar, total o parcialmente, la reserva sobre la cláusula de excepción política por medio de una declaración dirigida al Secretario General del Consejo de Europa, que entrará en vigor:","o":["el primer día del mes siguiente a su recepción.","en la fecha de su recepción.","transcurridos tres meses desde su recepción.","en la fecha de su publicación por el Secretario General."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en la fecha de su recepción</mark></span>El <span class=\"ref-norma\">art. 20.3 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"por medio de una declaración dirigida al Secretario General del Consejo de Europa, que entrará en vigor en la fecha de su recepción\"</span>. La retirada de la reserva es inmediata: surte efecto en la fecha de recepción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1237","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Exclusión de la cláusula de excepción política. Las reservas formuladas sobre la cláusula de excepción política serán válidas por un período de tres años a partir del primer día de la entrada en vigor del Convenio para la Parte de que se trate. No obstante:","o":["dichas reservas podrán ser renovadas por períodos de igual duración.","dichas reservas podrán ser renovadas por un único período de igual duración.","dichas reservas quedarán prorrogadas tácitamente por períodos de un año.","dichas reservas podrán renovarse por períodos de cinco años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">dichas reservas podrán ser renovadas por períodos de igual duración</mark></span>El <span class=\"ref-norma\">art. 20.5 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"No obstante, dichas reservas podrán ser renovadas por períodos de igual duración\"</span>. Tres años renovables por períodos de igual duración, sin límite de renovaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1238","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Exclusión de la cláusula de excepción política. Doce meses antes de la expiración de la reserva, el Secretario General del Consejo de Europa informará a la Parte de dicha expiración. Tres meses antes de la fecha de expiración, la Parte deberá notificar al Secretario General su intención de:","o":["mantener o retirar la reserva.","renovar o dejar caducar la reserva.","mantener la reserva por un nuevo período o sustituirla por una declaración.","mantener, modificar o retirar la reserva."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">mantener, modificar o retirar la reserva</mark></span>El <span class=\"ref-norma\">art. 20.6 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"la Parte deberá notificar al Secretario General su intención de mantener, modificar o retirar la reserva\"</span>. Las tres opciones de la Parte son mantener, modificar o retirar la reserva. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1239","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Exclusión de la cláusula de excepción política. A falta de notificación por la Parte de que se trate de su intención respecto de la reserva, el Secretario General informará a dicha Parte de que su reserva queda automáticamente prorrogada:","o":["por un período de tres meses.","por un período de un año.","por un período de seis meses.","por un período igual al de la reserva inicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por un período de seis meses</mark></span>El <span class=\"ref-norma\">art. 20.6 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"el Secretario General informará a dicha Parte de que su reserva queda automáticamente prorrogada por un período de seis meses\"</span>. La prórroga automática es de seis meses; si la Parte no notifica su decisión antes de que expire ese período, la reserva queda sin efecto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1240","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Exclusión de la cláusula de excepción política. Cuando una Parte decida no conceder la extradición en virtud de la aplicación de la reserva, someterá el asunto, sin excepción alguna y sin demora injustificada, a sus autoridades competentes para que se inicien actuaciones penales, salvo en caso de que:","o":["la Parte requirente haya retirado la solicitud de extradición mediante notificación escrita.","se hayan convenido otras disposiciones entre la Parte requirente y la Parte requerida.","el Secretario General del Consejo de Europa haya autorizado otra solución.","la persona reclamada sea nacional de un tercer Estado no Parte en el Convenio."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se hayan convenido otras disposiciones entre la Parte requirente y la Parte requerida</mark></span>El <span class=\"ref-norma\">art. 20.7 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"salvo en caso de que se hayan convenido otras disposiciones entre la Parte requirente y la Parte requerida\"</span>. Solo se exceptúa que las Partes requirente y requerida hayan convenido otras disposiciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1241","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Exclusión de la cláusula de excepción política. Si no se adopta ninguna decisión judicial sobre el fondo del asunto en la Parte requerida dentro de un plazo razonable, la Parte requirente podrá informar de ello al Secretario General del Consejo de Europa, que someterá la cuestión a la Consulta entre las Partes. Esta emitirá un dictamen y lo someterá al Comité de Ministros, que se reunirá:","o":["en su composición restringida a los Estados Partes.","en su composición ordinaria con todos los Estados miembros.","en sesión extraordinaria con representación de los Estados requirente y requerido.","en su composición restringida a la Parte requirente y la Parte requerida."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en su composición restringida a los Estados Partes</mark></span>El <span class=\"ref-norma\">art. 20.8 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"el Comité de Ministros se reunirá en su composición restringida a los Estados Partes\"</span>. Cuando ejerce estas funciones, el Comité de Ministros se reúne en su composición restringida a los Estados Partes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ENMIENDAS AL CONVENIO art. 27 · cuadro del temario ·","q":[{"i":"2-124","p":"Convenio del Consejo de Europa para la prevención del terrorismo. Enmiendas al Convenio. Podrán proponerse enmiendas al presente Convenio por:","o":["Cualquiera de las Partes o por el Secretario General del Consejo de Europa, previa consulta a las demás Partes.","El Comité de Ministros del Consejo de Europa, a propuesta de al menos un tercio de las Partes en el Convenio.","Cualquiera de las Partes, por el Comité de Ministros del Consejo de Europa o por la Consulta entre las Partes.","La Consulta entre las Partes, por mayoría de dos tercios, o por la Asamblea Parlamentaria del Consejo de Europa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cualquiera de las Partes, por el Comité de Ministros del Consejo de Europa o por la Consulta entre las Partes</mark></span>Según el <span class=\"ref-norma\">art. 27.1 del Convenio n.º 196 del Consejo de Europa</span>: <span class=\"ref-concepto\">\"Podrán proponerse enmiendas al presente Convenio por cualquiera de las Partes, por el Comité de Ministros del Consejo de Europa o por la Consulta entre las Partes\"</span>. Ficha RECUERDA R8 (y marca EXOF del temario). <i>(ficha RECUERDA R8 del temario)</i>"},{"i":"2-ia-1308","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Enmiendas al Convenio. Podrán proponerse enmiendas al Convenio por cualquiera de las Partes, por el Comité de Ministros del Consejo de Europa o por:","o":["el Secretario General del Consejo de Europa.","la Consulta entre las Partes.","la Asamblea Parlamentaria del Consejo de Europa.","un tercio de las Partes signatarias."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Consulta entre las Partes</mark></span>El <span class=\"ref-norma\">art. 27.1 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"Podrán proponerse enmiendas al presente Convenio por cualquiera de las Partes, por el Comité de Ministros del Consejo de Europa o por la Consulta entre las Partes\"</span>. Los legitimados son las Partes, el Comité de Ministros y la Consulta entre las Partes; el Secretario General solo comunica las propuestas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1309","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Enmiendas al Convenio. Toda enmienda propuesta por una Parte o por el Comité de Ministros será trasladada a la Consulta entre las Partes, que:","o":["someterá al Comité de Ministros su dictamen acerca de la enmienda propuesta.","aprobará o rechazará la enmienda propuesta por mayoría de las Partes, en los términos que establezca la propia norma.","la transmitirá a las Partes para que comuniquen su aceptación.","la someterá a la aceptación de las Partes en el plazo de un año."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">someterá al Comité de Ministros su dictamen acerca de la enmienda propuesta</mark></span>El <span class=\"ref-norma\">art. 27.3 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"toda enmienda propuesta por una Parte o por el Comité de Ministros será trasladada a la Consulta entre las Partes, que someterá al Comité de Ministros su dictamen acerca de la enmienda propuesta\"</span>. La Consulta emite un dictamen que somete al Comité de Ministros, que es quien puede aprobar la enmienda. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1310","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Enmiendas al Convenio. Toda enmienda aprobada por el Comité de Ministros entrará en vigor:","o":["el primer día del mes siguiente a la fecha en que la acepten dos tercios de las Partes y el Comité de Ministros, salvo que se disponga otra cosa en la normativa aplicable.","a los tres meses de la fecha de su aprobación por el Comité de Ministros, salvo objeción de alguna Parte.","el trigésimo día siguiente a la fecha en que la acepte la mayoría de las Partes ante el Secretario General.","el trigésimo día siguiente a la fecha en que todas las Partes hayan comunicado su aceptación al Secretario General."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el trigésimo día siguiente a la fecha en que todas las Partes hayan comunicado su aceptación al Secretario General</mark></span>El <span class=\"ref-norma\">art. 27.6 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"Toda enmienda aprobada en virtud del apartado 4 entrará en vigor el trigésimo día siguiente a la fecha en que todas las Partes hayan comunicado su aceptación al Secretario General\"</span>. Entra en vigor el trigésimo día siguiente a la comunicación de aceptación de todas las Partes, no de una mayoría. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"LAS PARTES SE CONSULTARÁN PERIÓDICAMENTE CON EL FIN DE: art. 30 · cuadro del temario","q":[{"i":"2-162","p":"Convenio del Consejo de Europa para la prevención del terrorismo. Consulta entre las Partes. La Consulta entre las Partes será convocada por el Secretario General del Consejo de Europa cada vez que lo considere necesario y, en cualquier caso, si lo solicita:","o":["Un tercio de las Partes o la Asamblea Parlamentaria.","La mayoría de las Partes o el Comité de Ministros.","Cualquiera de las Partes o el Comité Antiterrorista del Consejo de Europa.","La unanimidad de las Partes o el Tribunal Europeo de Derechos Humanos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La mayoría de las Partes o el Comité de Ministros</mark></span>Según el <span class=\"ref-norma\">art. 30.2 del Convenio n.º 196 del Consejo de Europa</span>: <span class=\"ref-concepto\">\"si lo solicita la mayoría de las Partes o el Comité de Ministros\"</span>. La convoca el Secretario General cuando lo considere necesario o si lo pide la mayoría de las Partes o el Comité de Ministros. <i>(marca EXOF del temario)</i>"},{"i":"2-ia-1315","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Consulta entre las Partes. Las Partes se consultarán periódicamente con el fin de efectuar propuestas para facilitar o mejorar la utilización y la aplicación efectivas del Convenio y, entre otros fines, con el de:","o":["aprobar las enmiendas propuestas al Convenio por mayoría de las Partes.","designar al Secretario General del Consejo de Europa como mediador en las controversias, conforme al procedimiento que se establezca reglamentariamente.","formular su opinión sobre la conformidad de una negativa de extradición que les sea sometida.","emitir dictámenes vinculantes sobre las reservas formuladas por las Partes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">formular su opinión sobre la conformidad de una negativa de extradición que les sea sometida</mark></span>El <span class=\"ref-norma\">art. 30.1 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"formular su opinión sobre la conformidad de una negativa de extradición que les sea sometida\"</span>. La Consulta opina sobre la conformidad de las negativas de extradición, propone y dictamina enmiendas y expresa opinión sobre la aplicación del Convenio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1316","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Consulta entre las Partes. La Consulta entre las Partes será convocada por el Secretario General del Consejo de Europa cada vez que lo considere necesario y, en cualquier caso, si lo solicita:","o":["un tercio de las Partes o el Comité de Ministros.","la mayoría de las Partes o el Comité de Ministros.","la mayoría de las Partes o la Asamblea Parlamentaria.","cualquiera de las Partes o el Comité de Ministros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la mayoría de las Partes o el Comité de Ministros</mark></span>El <span class=\"ref-norma\">art. 30.2 de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"será convocada por el Secretario General del Consejo de Europa cada vez que lo considere necesario y, en cualquier caso, si lo solicita la mayoría de las Partes o el Comité de Ministros\"</span>. La convoca el Secretario General, obligatoriamente a petición de la mayoría de las Partes o del Comité de Ministros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 17 y 18 — Examen especial y comunicación por indicio ✱ R12","q":[{"i":"2-ia-1546","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Políticas y procedimientos. Los sujetos obligados aprobarán por escrito y aplicarán políticas y procedimientos adecuados en materia de diligencia debida, información, conservación de documentos, control interno, evaluación y gestión de riesgos, garantía del cumplimiento de las disposiciones pertinentes y:","o":["formación, con objeto de prevenir e impedir operaciones relacionadas con el blanqueo de capitales o la financiación del terrorismo, salvo que se disponga otra cosa en la normativa aplicable.","auditoría, con objeto de detectar y comunicar operaciones relacionadas con el blanqueo de capitales.","supervisión, con objeto de prevenir e impedir infracciones de la normativa de prevención del blanqueo.","comunicación, con objeto de prevenir e impedir operaciones relacionadas con el blanqueo de capitales o la financiación del terrorismo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">comunicación, con objeto de prevenir e impedir operaciones relacionadas con el blanqueo de capitales o la financiación del terrorismo</mark></span>El <span class=\"ref-norma\">art. 26.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"garantía del cumplimiento de las disposiciones pertinentes y comunicación, con objeto de prevenir e impedir operaciones relacionadas con el blanqueo de capitales o la financiación del terrorismo\"</span>. La última materia es la comunicación; la finalidad es prevenir e impedir operaciones de blanqueo o financiación del terrorismo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1609","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Formación de empleados. Las medidas de formación de los empleados incluirán la participación debidamente acreditada en cursos específicos de formación permanente orientados a:","o":["detectar las operaciones que puedan estar relacionadas con el blanqueo de capitales o la financiación del terrorismo e instruirles sobre la forma de proceder en tales casos.","conocer la normativa de prevención del blanqueo de capitales y las sanciones aplicables a su incumplimiento, en los términos que establezca la propia norma, salvo que se disponga otra cosa en la normativa aplicable.","aplicar los procedimientos de diligencia debida y las políticas de admisión de clientes del sujeto obligado.","redactar las comunicaciones por indicio y los informes de examen especial de las operaciones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">detectar las operaciones que puedan estar relacionadas con el blanqueo de capitales o la financiación del terrorismo e instruirles sobre la forma de proceder en tales casos</mark></span>El <span class=\"ref-norma\">art. 29 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"cursos específicos de formación permanente orientados a detectar las operaciones que puedan estar relacionadas con el blanqueo de capitales o la financiación del terrorismo e instruirles sobre la forma de proceder en tales casos\"</span>. Los cursos se orientan a detectar operaciones sospechosas e instruir sobre cómo proceder. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1807","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Infracciones graves. Constituye infracción grave el incumplimiento de la obligación de aplicar medidas reforzadas de diligencia debida, así como el de:","o":["colaboración con el Servicio Ejecutivo sin requerimiento.","aplicación de medidas simplificadas sin comprobar el riesgo.","examen especial de las operaciones sospechosas.","seguimiento de los clientes de riesgo elevado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">examen especial de las operaciones sospechosas</mark></span>El <span class=\"ref-norma\">art. 52.1.f de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"El incumplimiento de la obligación de examen especial, en los términos del artículo 17\"</span>. El examen especial figura en la letra g) como infracción grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1110","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Disposición adicional primera. Modificación de la Ley 19/1993, de 28 de diciembre, sobre determinadas medidas de prevención del blanqueo de capitales. Los sujetos obligados examinarán con especial atención cualquier operación, con independencia de su cuantía, que pueda estar vinculada al blanqueo de capitales; en particular, toda operación compleja, inusual o que no tenga un propósito económico o lícito aparente, reseñando:","o":["en un registro los datos del cliente.","al Servicio Ejecutivo la identidad del cliente.","en un informe anual los hechos examinados.","por escrito los resultados del examen."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por escrito los resultados del examen</mark></span>El <span class=\"ref-norma\">disposición adicional primera (art. 3.2 de la Ley 19/1993) de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"examinarán con especial atención toda operación compleja, inusual o que no tenga un propósito económico o lícito aparente, reseñando por escrito los resultados del examen\"</span>. El examen especial se documenta por escrito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1135","p":"Convenio del Consejo de Europa para la prevención del terrorismo (Convenio n.º 196), hecho en Varsovia el 16 de mayo de 2005. Preámbulo. El Convenio reconoce que los delitos terroristas, así como los previstos por el propio Convenio, sean quienes fueren sus autores, no son en ningún caso justificables con consideraciones de naturaleza:","o":["política, ideológica, racial, étnica o religiosa, salvo que medie un conflicto armado.","política, filosófica, social, cultural, religiosa o de cualquier otra naturaleza análoga, conforme al procedimiento que se establezca reglamentariamente.","política, filosófica, ideológica, racial, étnica, religiosa o de cualquier otra naturaleza similar.","política, ideológica o religiosa, cuando no se afecte a la población civil."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">política, filosófica, ideológica, racial, étnica, religiosa o de cualquier otra naturaleza similar</mark></span>El <span class=\"ref-norma\">preámbulo de el Convenio n.º 196 del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"no son en ningún caso justificables con consideraciones de naturaleza política, filosófica, ideológica, racial, étnica, religiosa o de cualquier otra naturaleza similar\"</span>. La lista es política, filosófica, ideológica, racial, étnica, religiosa o similar, y no admite excepción alguna. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1519","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Examen especial. Los sujetos obligados examinarán con especial atención cualquier hecho u operación, con independencia de su cuantía, que por su naturaleza pueda estar relacionado con el blanqueo de capitales o la financiación del terrorismo, reseñando:","o":["en un registro electrónico los datos del cliente.","ante el órgano de control interno la identidad del cliente.","por escrito los resultados del examen.","en un informe trimestral los hechos examinados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por escrito los resultados del examen</mark></span>El <span class=\"ref-norma\">art. 17 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"reseñando por escrito los resultados del examen\"</span>. Los resultados del examen especial se reseñan por escrito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1520","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Examen especial. Los sujetos obligados examinarán con especial atención toda operación o pauta de comportamiento compleja, inusual o sin un propósito económico o lícito aparente, o que presente:","o":["indicios de evasión fiscal.","indicios de simulación o fraude.","una cuantía superior a los umbrales reglamentarios.","una vinculación con países de riesgo elevado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">indicios de simulación o fraude</mark></span>El <span class=\"ref-norma\">art. 17 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"o que presente indicios de simulación o fraude\"</span>. Se examinan las operaciones complejas, inusuales, sin propósito económico o lícito aparente o con indicios de simulación o fraude. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1521","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Examen especial. Al establecer las medidas de control interno, los sujetos obligados concretarán el modo en que se dará cumplimiento al deber de examen especial, que incluirá la elaboración y difusión entre sus directivos, empleados y agentes de una relación de operaciones susceptibles de estar relacionadas con el blanqueo, la periódica revisión de tal relación y:","o":["la utilización de aplicaciones informáticas apropiadas, teniendo en cuenta el tipo de operaciones, sector de negocio, ámbito geográfico y volumen de la información.","la formación anual de directivos, empleados y agentes sobre las operaciones susceptibles de examen especial y su revisión, en los términos que establezca la propia norma.","la comunicación de la relación al Servicio Ejecutivo para su aprobación previa y su posterior difusión.","la auditoría anual de la relación por un experto externo independiente y su informe al órgano de control interno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la utilización de aplicaciones informáticas apropiadas, teniendo en cuenta el tipo de operaciones, sector de negocio, ámbito geográfico y volumen de la información</mark></span>El <span class=\"ref-norma\">art. 17 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"la periódica revisión de tal relación y la utilización de aplicaciones informáticas apropiadas, teniendo en cuenta el tipo de operaciones, sector de negocio, ámbito geográfico y volumen de la información\"</span>. Se añade la utilización de aplicaciones informáticas apropiadas, según tipo de operaciones, sector, ámbito geográfico y volumen de información. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1528","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Comunicación por indicio. Los directivos o empleados de los sujetos obligados podrán comunicar directamente al Servicio Ejecutivo las operaciones de que conocieran y que estimen sospechosas, en los casos en que, habiendo sido puestas de manifiesto internamente:","o":["el órgano de control interno hubiera decidido no comunicarlas al Servicio Ejecutivo, sin perjuicio de lo dispuesto en otras disposiciones.","el sujeto obligado no hubiese informado al directivo o empleado comunicante del curso dado a su comunicación.","hubieran transcurrido diez días sin que el sujeto obligado las comunicara.","el representante ante el Servicio Ejecutivo hubiera archivado la comunicación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el sujeto obligado no hubiese informado al directivo o empleado comunicante del curso dado a su comunicación</mark></span>El <span class=\"ref-norma\">art. 18.4 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"en los casos en que, habiendo sido puestas de manifiesto internamente, el sujeto obligado no hubiese informado al directivo o empleado comunicante del curso dado a su comunicación\"</span>. Es una vía subsidiaria cuando no se le informa del curso dado a su comunicación interna. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-36","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Fichero de titularidades financieras. ¿Qué órgano, como encargado del tratamiento, determinará las características técnicas del fichero, pudiendo aprobar las instrucciones pertinentes?:","o":["Servicio Ejecutivo de la Comisión.","La Secretaría de la Comisión.","El Comité Permanente.","El Ministro de Economía y Empresa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Servicio Ejecutivo de la Comisión.</mark></span><span class=\"ref-norma\">Ley 10/2010, art. 43</span> dispone: <span class=\"ref-concepto\">\"El Servicio Ejecutivo de la Comisión, como encargado del tratamiento, determinará, con arreglo a lo establecido en la Ley Orgánica 3/2018, de 5 de diciembre, y en el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016, las características técnicas del fichero, pudiendo aprobar las instrucciones pertinentes\"</span>."},{"i":"2-55","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. ¿Qué órgano ejerce las funciones de la Unidad de Inteligencia Financiera?:","o":["El Comité Permanente.","La Secretaría de la Comisión.","El Servicio Ejecutivo de la Comisión.","La Comisión del blanqueo de capitales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Servicio Ejecutivo de la Comisión.</mark></span><span class=\"ref-norma\">Art. 45 · Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo</span>. La respuesta correcta es la C porque, conforme a la organización institucional de la Ley 10/2010 (artículo 45), el Servicio Ejecutivo de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias actúa como unidad de inteligencia financiera, siendo el órgano que recibe las comunicaciones de operaciones sospechosas (artículo 18), analiza la información y elabora los informes de inteligencia financiera (artículo 46), ejerciendo así las funciones propias de dicha unidad."},{"i":"2-105","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Órganos de apoyo de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias. La Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias llevará a cabo su cometido con el apoyo de:","o":["El Comité Permanente y el Comité de Inteligencia Financiera.","La Secretaría de la Comisión y el Servicio Ejecutivo de la Comisión.","La Secretaría de Estado de Economía y el Banco de España.","El Servicio Ejecutivo y la Comisión de Vigilancia de Actividades de Financiación del Terrorismo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Secretaría de la Comisión y el Servicio Ejecutivo de la Comisión</mark></span>Según el <span class=\"ref-norma\">art. 45.1 de la Ley 10/2010</span>: <span class=\"ref-concepto\">\"llevará a cabo su cometido con el apoyo de la Secretaría de la Comisión y del Servicio Ejecutivo de la Comisión\"</span>. Los dos órganos de apoyo son la Secretaría y el Servicio Ejecutivo (SEPBLAC). <i>(sello «PREGUNTA EXAMEN» del temario)</i>"},{"i":"2-128","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Comunicación por indicio. Los sujetos obligados comunicarán cualquier hecho u operación, incluso la mera tentativa, respecto al que, tras el examen especial, exista indicio o certeza de que está relacionado con el blanqueo de capitales o la financiación del terrorismo:","o":["Previo requerimiento, a la Secretaría de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias.","Por iniciativa propia, al Ministerio Fiscal o a la autoridad judicial competente del lugar donde se produjo la operación.","Por iniciativa propia, al Servicio Ejecutivo de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias.","Previo requerimiento, al Comité Permanente de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por iniciativa propia, al Servicio Ejecutivo de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias</mark></span>Según el <span class=\"ref-norma\">art. 18.1 de la Ley 10/2010</span>: <span class=\"ref-concepto\">\"Los sujetos obligados comunicarán, por iniciativa propia, al Servicio Ejecutivo de la Comisión de Pre\"</span>. Ficha RECUERDA R12. <i>(ficha RECUERDA R12 del temario)</i>"},{"i":"2-ia-1508","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Personas con responsabilidad pública. La lista en la que se detallará qué tipo de funciones y puestos determinan la consideración de persona con responsabilidad pública española será elaborada y publicada por:","o":["el Servicio Ejecutivo de la Comisión de Prevención del Blanqueo de Capitales, sin perjuicio de lo dispuesto en otras disposiciones.","la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias.","la Secretaría General del Tesoro y Financiación Internacional.","el Ministerio de Hacienda y Función Pública."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias</mark></span>El <span class=\"ref-norma\">art. 14.3 (último párrafo) de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"La Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias elaborará y publicará una lista en la que se detallará qué tipo de funciones y puestos determinan la consideración de persona con responsabilidad pública española\"</span>. La elabora y publica la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1522","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Comunicación por indicio. Los sujetos obligados comunicarán, por iniciativa propia, al Servicio Ejecutivo de la Comisión cualquier hecho u operación, incluso la mera tentativa, respecto al que, tras el examen especial, exista:","o":["certeza de que está relacionado con el blanqueo de capitales o la financiación del terrorismo, salvo que se disponga otra cosa en la normativa aplicable.","sospecha fundada de la comisión de un delito de blanqueo de capitales.","indicio de que supera los umbrales reglamentarios de comunicación sistemática.","indicio o certeza de que está relacionado con el blanqueo de capitales o la financiación del terrorismo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">indicio o certeza de que está relacionado con el blanqueo de capitales o la financiación del terrorismo</mark></span>El <span class=\"ref-norma\">art. 18.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"cualquier hecho u operación, incluso la mera tentativa, respecto al que, tras el examen especial a que se refiere el artículo precedente, exista indicio o certeza de que está relacionado con el blanqueo de capitales o la financiación del terrorismo\"</span>. Basta el indicio o la certeza, tras el examen especial, e incluso la mera tentativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1527","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Comunicación por indicio. La comunicación por indicio se efectuará por los sujetos obligados en el soporte y con el formato que determine:","o":["la Secretaría de la Comisión.","el Comité Permanente de la Comisión, conforme al procedimiento que se establezca reglamentariamente.","el Servicio Ejecutivo de la Comisión.","el Ministerio de Economía."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Servicio Ejecutivo de la Comisión</mark></span>El <span class=\"ref-norma\">art. 18.3 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"La comunicación por indicio se efectuará por los sujetos obligados en el soporte y con el formato que determine el Servicio Ejecutivo de la Comisión\"</span>. Lo determina el Servicio Ejecutivo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1532","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Comunicación sistemática. De no existir operaciones susceptibles de comunicación sistemática, los sujetos obligados:","o":["quedarán exentos de la obligación de comunicación sistemática en ese periodo, sin perjuicio de lo dispuesto en otras disposiciones.","comunicarán esta circunstancia al Servicio Ejecutivo con la periodicidad que se determine reglamentariamente.","conservarán un registro de la inexistencia de operaciones durante diez años.","lo comunicarán a la Secretaría de la Comisión cuando lo requiera."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">comunicarán esta circunstancia al Servicio Ejecutivo con la periodicidad que se determine reglamentariamente</mark></span>El <span class=\"ref-norma\">art. 20.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"De no existir operaciones susceptibles de comunicación los sujetos obligados comunicarán esta circunstancia al Servicio Ejecutivo de la Comisión con la periodicidad que se determine reglamentariamente\"</span>. También debe comunicarse la ausencia de operaciones, con la periodicidad reglamentaria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1551","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Políticas y procedimientos. El Servicio Ejecutivo de la Comisión y, en caso de convenio, los órganos supervisores de las entidades financieras podrán proponer la formulación de requerimientos instando a los sujetos obligados a adoptar las medidas correctoras oportunas respecto de sus manuales y procedimientos internos. La propuesta se dirige:","o":["a la Secretaría de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias, conforme al procedimiento que se establezca reglamentariamente.","al Pleno de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias.","al Comité Permanente de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias.","al Ministro de Economía, a propuesta de la Secretaría de Estado de Economía."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al Comité Permanente de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias</mark></span>El <span class=\"ref-norma\">art. 26.6 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"podrán proponer al Comité Permanente de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias la formulación de requerimientos instando a los sujetos obligados a adoptar las medidas correctoras oportunas\"</span>. La propuesta se eleva al Comité Permanente de la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1610","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Protección e idoneidad de empleados, directivos y agentes. Los sujetos obligados adoptarán las medidas adecuadas para mantener la confidencialidad sobre la identidad de los empleados, directivos o agentes que hayan realizado una comunicación a los órganos de control interno. Comparecerá en toda clase de procedimientos administrativos o judiciales en relación con los datos de las comunicaciones:","o":["el empleado o directivo que realizó la comunicación, salvo que se disponga otra cosa en la normativa aplicable.","el responsable del órgano de control interno.","el responsable de la unidad técnica de prevención.","el representante ante el Servicio Ejecutivo de la Comisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el representante ante el Servicio Ejecutivo de la Comisión</mark></span>El <span class=\"ref-norma\">art. 30.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"El representante a que se refiere el artículo 26 ter será la persona que comparecerá en toda clase de procedimientos administrativos o judiciales en relación con los datos recogidos en las comunicaciones\"</span>. Comparece el representante ante el Servicio Ejecutivo, no el empleado que comunicó. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1614","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Sucursales y filiales en terceros países. Cuando el Servicio Ejecutivo de la Comisión reciba la información de que el derecho del tercer país no permite medidas equivalentes, podrá proponer la formulación de requerimientos para la adopción de medidas de obligado cumplimiento:","o":["a la Secretaría de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias, salvo que se disponga otra cosa en la normativa aplicable.","al Pleno de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias.","al Ministro de Economía, Comercio y Empresa.","al Comité Permanente de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">al Comité Permanente de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias</mark></span>El <span class=\"ref-norma\">art. 31.2 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"que podrá proponer al Comité Permanente de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias la formulación de requerimientos para la adopción de medidas de obligado cumplimiento\"</span>. La propuesta se dirige al Comité Permanente de la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1640","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Obligación de declarar. En el supuesto de entradas y salidas procedentes o con destino a un país que no forma parte de la Unión Europea, el modelo de declaración será:","o":["el aprobado por Orden del titular del Ministerio de Asuntos Económicos y Transformación Digital.","el aprobado por la Comisión Europea en el correspondiente Reglamento de Ejecución.","el aprobado por el Servicio Ejecutivo de la Comisión de Prevención del Blanqueo de Capitales.","el aprobado por Resolución de la Agencia Estatal de Administración Tributaria."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el aprobado por la Comisión Europea en el correspondiente Reglamento de Ejecución</mark></span>El <span class=\"ref-norma\">art. 34.4 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"el aprobado por la Comisión Europea en el correspondiente Reglamento de Ejecución\"</span>. Con terceros países se usa el modelo de la Comisión Europea; en el resto de supuestos, el aprobado por Orden ministerial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1647","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Control e intervención de los medios de pago. Los medios de pago intervenidos se ingresarán, directamente o por transferencia, en las cuentas abiertas a nombre de:","o":["el Servicio Ejecutivo de la Comisión de Prevención del Blanqueo de Capitales, conforme al procedimiento que se establezca reglamentariamente.","la Agencia Estatal de Administración Tributaria.","la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias.","el Tesoro Público, a disposición de la Secretaría de la Comisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias</mark></span>El <span class=\"ref-norma\">art. 35.3 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Los medios de pago intervenidos se ingresarán, directamente o por transferencia, en las cuentas abiertas a nombre de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias\"</span>. Se ingresan en cuentas a nombre de la propia Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1651","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Intercambio de información. La información obtenida a partir de la declaración o de los controles podrá transmitirse a las autoridades competentes de otros Estados. Cuando haya indicios de relación con el producto de un fraude o con cualquier otra actividad ilegal que perjudique a los intereses financieros de la Comunidad Europea, dicha información se transmitirá también:","o":["a la Oficina Europea de Lucha contra el Fraude.","a la Fiscalía Europea.","a la Comisión Europea.","al Parlamento Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a la Comisión Europea</mark></span>El <span class=\"ref-norma\">art. 37 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"dicha información se transmitirá también a la Comisión Europea\"</span>. En esos casos se transmite también a la Comisión Europea. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1666","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Sanciones y contramedidas financieras internacionales. Competerá la supervisión e inspección del cumplimiento de lo dispuesto sobre sanciones y contramedidas financieras, incluido el cumplimiento de los requisitos fijados en los protocolos, a:","o":["la Dirección General del Tesoro y Política Financiera.","la Secretaría de la Comisión.","el Comité Permanente de la Comisión.","el Servicio Ejecutivo de la Comisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el Servicio Ejecutivo de la Comisión</mark></span>El <span class=\"ref-norma\">art. 42.4 (redacción de 30/03/2026) de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Competerá al Servicio Ejecutivo de la Comisión la supervisión e inspección del cumplimiento de lo dispuesto en este artículo\"</span>. La supervisión e inspección es del Servicio Ejecutivo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1749","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Cooperación internacional. La Secretaría de la Comisión, el Servicio Ejecutivo o, en caso de convenio, los supervisores financieros cooperarán, por propia iniciativa o previa solicitud, en tiempo oportuno y gratuitamente, con otras autoridades competentes de la Unión Europea. En el marco de esta cooperación se facilitará a la Autoridad Bancaria Europea:","o":["la información necesaria para sus obligaciones en materia de prevención del blanqueo y del terrorismo.","los informes de inteligencia financiera que elabore el Servicio Ejecutivo de la Comisión sobre operaciones.","las estadísticas anuales sobre blanqueo de capitales y financiación del terrorismo del país.","el análisis nacional de riesgos de blanqueo de capitales y de financiación del terrorismo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la información necesaria para sus obligaciones en materia de prevención del blanqueo y del terrorismo</mark></span>El <span class=\"ref-norma\">art. 48 bis.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"a la Autoridad Bancaria Europea la información necesaria para permitirle llevar a cabo sus obligaciones en materia de prevención del blanqueo de capitales y de la financiación del terrorismo\"</span>. A la Autoridad Bancaria Europea se le facilita la información necesaria para sus obligaciones de prevención. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1751","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Cooperación internacional. El intercambio de información del Servicio Ejecutivo con Unidades de Inteligencia Financiera de terceros países no miembros de la Unión Europea se realizará de acuerdo con los principios del Grupo Egmont o en los términos del correspondiente memorando de entendimiento, que serán suscritos por:","o":["el Secretario de la Comisión, previa autorización del Comité Permanente y previo informe de la Agencia Española de Protección de Datos, conforme al procedimiento que se establezca reglamentariamente.","el Director del Servicio Ejecutivo, previa autorización del Ministro de Economía y previo informe del Banco de España.","el Director del Servicio Ejecutivo, previa autorización de la Comisión y previo informe favorable de la Agencia Española de Protección de Datos.","el Presidente de la Comisión, previa autorización del Pleno y previo informe favorable de la Agencia Española de Protección de Datos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Director del Servicio Ejecutivo, previa autorización de la Comisión y previo informe favorable de la Agencia Española de Protección de Datos</mark></span>El <span class=\"ref-norma\">art. 48 bis.4 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Los memorandos de entendimiento con Unidades de Inteligencia Financiera serán suscritos por el Director del Servicio Ejecutivo, previa autorización de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias, debiendo contar con el previo informe favorable de la Agencia Española de Protección de Datos\"</span>. Los suscribe el Director del Servicio Ejecutivo con autorización de la Comisión y previo informe favorable de la Agencia Española de Protección de Datos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1754","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Deber de secreto. Todas las personas que desempeñen o hayan desempeñado una actividad para la Comisión o para cualquiera de sus órganos y hayan tenido conocimiento de sus actuaciones o de datos de carácter reservado están obligadas a mantener el debido secreto. No podrán publicar, comunicar o exhibir datos o documentos reservados, ni siquiera después de haber cesado en el servicio, salvo:","o":["autorización del Comité Permanente de la Comisión de Prevención del Blanqueo, salvo que se disponga otra cosa en la normativa aplicable.","requerimiento judicial dirigido a la persona que haya cesado en el servicio.","consentimiento expreso de los implicados en las actuaciones.","permiso expreso otorgado por la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">permiso expreso otorgado por la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias</mark></span>El <span class=\"ref-norma\">art. 49.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"ni siquiera después de haber cesado en el servicio, salvo permiso expreso otorgado por la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias\"</span>. El deber de secreto subsiste tras el cese, salvo permiso expreso de la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1761","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Infracciones muy graves. Constituirá infracción muy grave el incumplimiento de la obligación de colaboración con la Comisión cuando medie:","o":["requerimiento escrito de la propia Comisión de Prevención del Blanqueo de Capitales.","requerimiento escrito de cualquiera de los órganos de apoyo de la Comisión de Prevención.","requerimiento verbal de la Comisión o de sus órganos de apoyo en una inspección.","resolución del Comité Permanente con apercibimiento expreso de sanción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">requerimiento escrito de la propia Comisión de Prevención del Blanqueo de Capitales</mark></span>El <span class=\"ref-norma\">art. 51.1.b de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"El incumplimiento de la obligación de colaboración establecida en el artículo 21 cuando medie requerimiento escrito de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias\"</span>. Es muy grave si el requerimiento escrito es de la propia Comisión; si lo es de uno de sus órganos de apoyo, es grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1861","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Comunicación de infracciones. Los empleados, directivos y agentes de los sujetos obligados que conozcan hechos o situaciones que puedan ser constitutivos de infracciones contempladas en la Ley, los podrán poner en conocimiento:","o":["del Servicio Ejecutivo de la Comisión.","de la Secretaría de la Comisión.","del Comité Permanente de la Comisión.","del órgano de control interno del sujeto obligado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">del Servicio Ejecutivo de la Comisión</mark></span>El <span class=\"ref-norma\">art. 63.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"los podrán poner en conocimiento del Servicio Ejecutivo de la Comisión\"</span>. La comunicación de infracciones se dirige al Servicio Ejecutivo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1923","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Disposición adicional quinta. Forma y plazo para la declaración en el Fichero de Titularidades Financieras. En el plazo máximo de doce meses desde la entrada en vigor de la ley, establecerá la forma y plazo para realizar la declaración inicial de las cuentas de pago y cajas de seguridad al Fichero de Titularidades Financieras:","o":["la Secretaría de la Comisión.","el Comité Permanente de la Comisión, conforme al procedimiento que se establezca reglamentariamente.","el Servicio Ejecutivo de la Comisión.","la Secretaría de Estado de Economía."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Servicio Ejecutivo de la Comisión</mark></span>El <span class=\"ref-norma\">disposición adicional quinta de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"el Servicio Ejecutivo de la Comisión establecerá la forma y plazo para realizar la declaración inicial de las cuentas de pago y cajas de seguridad\"</span>. Lo establece el Servicio Ejecutivo en doce meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1931","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Disposición transitoria octava. Convenios con los órganos supervisores de las entidades financieras. En tanto no se suscriban los convenios con los órganos supervisores de las entidades financieras, mantendrán su vigencia:","o":["las competencias de supervisión de los órganos supervisores sobre los sujetos obligados, conforme al procedimiento que se establezca reglamentariamente.","los protocolos de actuación aprobados por la Comisión de Prevención del Blanqueo.","los convenios de colaboración existentes entre los órganos supervisores y el Servicio Ejecutivo de la Comisión.","las instrucciones del Banco de España sobre control interno de las entidades."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los convenios de colaboración existentes entre los órganos supervisores y el Servicio Ejecutivo de la Comisión</mark></span>El <span class=\"ref-norma\">disposición transitoria octava de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"mantendrán su vigencia los convenios de colaboración actualmente existentes entre los órganos supervisores de las entidades financieras y el Servicio Ejecutivo de la Comisión\"</span>. Siguen vigentes los convenios existentes con el Servicio Ejecutivo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1523","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Comunicación por indicio. Se consideran operaciones por indicio y se comunicarán al Servicio Ejecutivo los casos que, tras el examen especial, el sujeto obligado conozca, sospeche o tenga motivos razonables para sospechar que tengan relación con el blanqueo de capitales, con sus delitos precedentes o con la financiación del terrorismo, incluyendo aquellos casos que muestren:","o":["una cuantía superior a los umbrales reglamentarios y una vinculación con clientes de riesgo, sin justificación económica, profesional o de negocio, conforme al procedimiento que se establezca reglamentariamente.","una falta de correspondencia con el perfil de riesgo asignado al cliente y con su documentación, sin justificación económica o de negocio.","una falta de correspondencia ostensible con la naturaleza, volumen de actividad o antecedentes operativos de los clientes, sin justificación económica, profesional o de negocio.","una falta de correspondencia con las operaciones habituales del sector y de la zona geográfica, sin justificación económica o profesional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">una falta de correspondencia ostensible con la naturaleza, volumen de actividad o antecedentes operativos de los clientes, sin justificación económica, profesional o de negocio</mark></span>El <span class=\"ref-norma\">art. 18.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"incluyendo aquellos casos que muestren una falta de correspondencia ostensible con la naturaleza, volumen de actividad o antecedentes operativos de los clientes, siempre que en el examen especial no se aprecie justificación económica, profesional o de negocio para la realización de las operaciones\"</span>. La falta de correspondencia ostensible se mide frente a la naturaleza, volumen de actividad o antecedentes operativos del cliente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1524","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Comunicación por indicio. Las comunicaciones por indicio se efectuarán sin dilación, de conformidad con los procedimientos correspondientes, y contendrán, en todo caso, entre otra información, la relación e identificación de las personas que participan en la operación y concepto de su participación, y:","o":["el patrimonio conocido de dichas personas y su origen declarado.","la actividad conocida de dichas personas y correspondencia entre la actividad y la operación.","la política de admisión de clientes aplicada a dichas personas.","el nivel de riesgo asignado a dichas personas por el sujeto obligado, sin perjuicio de lo dispuesto en otras disposiciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la actividad conocida de dichas personas y correspondencia entre la actividad y la operación</mark></span>El <span class=\"ref-norma\">art. 18.2 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Actividad conocida de las personas físicas o jurídicas que participan en la operación y correspondencia entre la actividad y la operación\"</span>. También deben incluirse las operaciones vinculadas, las gestiones de investigación realizadas, la exposición de circunstancias y otros datos reglamentarios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1525","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Comunicación por indicio. En los casos en que el Servicio Ejecutivo de la Comisión estime que el examen especial realizado resulta insuficiente:","o":["devolverá la comunicación al sujeto obligado para que profundice en el examen, expresando sucintamente los motivos de la devolución y el contenido a examinar.","archivará la comunicación y lo notificará al sujeto obligado, que podrá presentar una nueva comunicación una vez ampliado su examen especial, en los términos que establezca la propia norma.","abrirá un expediente sancionador al sujeto obligado por incumplimiento del deber de examen especial de las operaciones.","solicitará al órgano de control interno del sujeto obligado un informe complementario sobre la operación comunicada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">devolverá la comunicación al sujeto obligado para que profundice en el examen, expresando sucintamente los motivos de la devolución y el contenido a examinar</mark></span>El <span class=\"ref-norma\">art. 18.2 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"devolverá la comunicación al sujeto obligado a efectos de que por éste se profundice en el examen de la operación, en la que se expresarán sucintamente los motivos de la devolución y el contenido a examinar\"</span>. La comunicación se devuelve para profundizar en el examen, con expresión sucinta de motivos y contenido. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1526","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Comunicación por indicio. En el caso de operaciones meramente intentadas, el sujeto obligado:","o":["se abstendrá de comunicar la operación al Servicio Ejecutivo por no haberse llegado a ejecutar.","comunicará la operación al Servicio Ejecutivo como si hubiera sido ejecutada, indicando solo su cuantía, salvo que se disponga otra cosa en la normativa aplicable.","conservará la información durante diez años, que comunicará solo si el cliente reitera el intento.","registrará la operación como no ejecutada, comunicando al Servicio Ejecutivo la información que se haya podido obtener."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">registrará la operación como no ejecutada, comunicando al Servicio Ejecutivo la información que se haya podido obtener</mark></span>El <span class=\"ref-norma\">art. 18.2 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"En el caso de operaciones meramente intentadas, el sujeto obligado registrará la operación como no ejecutada, comunicando al Servicio Ejecutivo de la Comisión la información que se haya podido obtener\"</span>. Se registra como no ejecutada y se comunica la información obtenida. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1533","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Comunicación sistemática. Cuando las operaciones sujetas a comunicación sistemática presenten indicios o certeza de estar relacionadas con el blanqueo de capitales o la financiación del terrorismo:","o":["se estará a lo dispuesto para el examen especial, la comunicación por indicio y la abstención de ejecución.","se comunicarán únicamente a través del procedimiento de comunicación sistemática.","se suspenderá la obligación de comunicación sistemática hasta concluir el examen especial, en los términos que establezca la propia norma.","se comunicarán a la Secretaría de la Comisión para su instrucción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se estará a lo dispuesto para el examen especial, la comunicación por indicio y la abstención de ejecución</mark></span>El <span class=\"ref-norma\">art. 20.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"cuando las operaciones sujetas a comunicación sistemática presenten indicios o certeza de estar relacionadas con el blanqueo de capitales o la financiación del terrorismo, se estará a lo dispuesto en los artículos 17, 18 y 19\"</span>. Se aplican el examen especial, la comunicación por indicio y la abstención de ejecución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1563","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Órganos centralizados de prevención. Los órganos centralizados de prevención examinarán, por propia iniciativa o a petición de los profesionales incorporados, las operaciones susceptibles de examen especial, comunicándolas al Servicio Ejecutivo de la Comisión:","o":["cuando superen los umbrales establecidos para la comunicación sistemática.","cuando lo solicite el profesional incorporado que las hubiera puesto de manifiesto.","cuando concurran las circunstancias establecidas para la comunicación por indicio.","cuando lo autorice el Colegio profesional al que pertenezca el profesional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cuando concurran las circunstancias establecidas para la comunicación por indicio</mark></span>El <span class=\"ref-norma\">art. 27.2 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"comunicándolas al Servicio Ejecutivo de la Comisión cuando concurran las circunstancias establecidas en el artículo 18\"</span>. Las comunican cuando concurran las circunstancias de la comunicación por indicio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 25 — Conservación de documentos R13","q":[{"i":"2-68","p":"Ley 10/2010, de prevención del blanqueo de capitales y financiación del terrorismo. Conservación de documentos. Los sujetos obligados conservarán durante un período de _____ la documentación en que se formalice el cumplimiento de las obligaciones establecidas en la presente ley, procediendo tras el mismo a su eliminación.","o":["Tres años.","Diez años.","Cinco años.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez años.</mark></span><span class=\"ref-norma\">Art. 25.1 · Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo</span>. El art. 25.1 de la Ley 10/2010 establece: \"Los sujetos obligados conservarán durante un período de diez años la documentación en que se formalice el cumplimiento de las obligaciones establecidas en la presente ley, procediendo tras el mismo a su eliminación.\""},{"i":"2-ia-1653","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Fundaciones y asociaciones. El Protectorado y el Patronato y el personal con responsabilidades en la gestión de las fundaciones velarán para que éstas no sean utilizadas para el blanqueo de capitales o para canalizar fondos o recursos a las personas o entidades vinculadas a grupos u organizaciones terroristas. Las fundaciones conservarán registros con la identificación de todas las personas que aporten o reciban a título gratuito fondos o recursos durante:","o":["el plazo establecido para la conservación de documentos, que es de diez años.","el plazo de seis años que se establecía en la antigua Ley 19/1993, en los términos que establezca la propia norma.","el plazo de cinco años desde la terminación de la relación.","el plazo que fije el Protectorado en función del riesgo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el plazo establecido para la conservación de documentos, que es de diez años</mark></span>El <span class=\"ref-norma\">art. 39 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"todas las fundaciones conservarán durante el plazo establecido en el artículo 25 registros con la identificación de todas las personas que aporten o reciban a título gratuito fondos o recursos de la fundación\"</span>. Remite al plazo general de conservación de documentos (diez años). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-175","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Sanciones por infracciones muy graves. A quienes, ejerciendo cargos de administración o dirección, sean responsables de una infracción muy grave podrá imponerse la separación del cargo, con inhabilitación para ejercer cargos en la misma entidad por un plazo máximo de:","o":["Diez años.","Cinco años.","Tres años.","Quince años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez años</mark></span>Según el <span class=\"ref-norma\">art. 56.3 b) de la Ley 10/2010</span>: <span class=\"ref-concepto\">\"por un plazo máximo de diez años\"</span>. Además, multa de entre 60.000 y 10.000.000 euros y amonestación pública. <i>(marca EXOF del temario)</i>"},{"i":"2-ia-1826","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Sanciones por infracciones muy graves. Entre las sanciones aplicables a los administradores o directivos responsables de infracciones muy graves figura la separación del cargo, con inhabilitación para ejercer cargos de administración o dirección en cualquier entidad sujeta a la Ley por un plazo máximo de:","o":["cinco años.","quince años.","tres años.","diez años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">diez años</mark></span>El <span class=\"ref-norma\">art. 56.3.b de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Separación del cargo, con inhabilitación para ejercer cargos de administración o dirección en cualquier entidad de las sujetas a esta ley por un plazo máximo de diez años\"</span>. La inhabilitación es de hasta diez años en las muy graves y hasta cinco en las graves. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1046","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Graduación de sanciones. Para graduar las sanciones se tendrá en cuenta, entre otras circunstancias, la conducta anterior del interesado en relación con las normas en materia de movimientos de capitales y pagos exteriores, tomando en consideración las sanciones firmes que le hubieran sido impuestas durante los últimos:","o":["tres años.","cuatro años.","diez años.","cinco años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cinco años</mark></span>El <span class=\"ref-norma\">art. 10.e de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"tomando en consideración al efecto las sanciones firmes que le hubieran sido impuestas durante los últimos cinco años\"</span>. Se computan las sanciones firmes de los últimos cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1542","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Conservación de documentos. Los sujetos obligados conservarán durante un período de diez años la documentación en que se formalice el cumplimiento de las obligaciones establecidas en la Ley, procediendo tras el mismo a su eliminación. Transcurridos cinco años desde la terminación de la relación de negocios o la ejecución de la operación ocasional, la documentación conservada únicamente será accesible por:","o":["el Servicio Ejecutivo de la Comisión y los órganos supervisores de las entidades financieras, previo requerimiento.","los órganos de control interno del sujeto obligado, las autoridades judiciales y policiales y el Servicio Ejecutivo.","el representante ante el Servicio Ejecutivo, el órgano de control interno y los auditores externos del sujeto obligado, salvo que se disponga otra cosa en la normativa aplicable.","los órganos de control interno del sujeto obligado, con inclusión de las unidades técnicas de prevención, y los encargados de su defensa legal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los órganos de control interno del sujeto obligado, con inclusión de las unidades técnicas de prevención, y los encargados de su defensa legal</mark></span>El <span class=\"ref-norma\">art. 25.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Transcurridos cinco años desde la terminación de la relación de negocios o la ejecución de la operación ocasional, la documentación conservada únicamente será accesible por los órganos de control interno del sujeto obligado, con inclusión de las unidades técnicas de prevención, y, en su caso, aquellos encargados de su defensa legal\"</span>. Pasados cinco años, solo acceden los órganos de control interno, incluidas las unidades técnicas de prevención, y los encargados de la defensa legal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1625","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Sistemas comunes de información. Los datos serán facilitados a los sistemas comunes de información, y canalizadas las solicitudes de acceso a los mismos, por:","o":["los órganos de control interno.","los representantes ante el Servicio Ejecutivo.","las unidades técnicas de prevención.","los órganos centralizados de prevención."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los órganos de control interno</mark></span>El <span class=\"ref-norma\">art. 32 ter.3 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Los datos serán facilitados al sistema por los órganos de control interno previstos en el artículo 26 ter\"</span>. Los datos los facilitan y los accesos los canalizan los órganos de control interno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1543","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Conservación de documentos. Los sujetos obligados conservarán copia de los documentos exigibles en aplicación de las medidas de diligencia debida durante un periodo de diez años desde:","o":["el establecimiento de la relación de negocios o la identificación del cliente.","la comunicación de la operación al Servicio Ejecutivo.","la terminación de la relación de negocios o la ejecución de la operación.","la última actualización de los datos del cliente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la terminación de la relación de negocios o la ejecución de la operación</mark></span>El <span class=\"ref-norma\">art. 25.1.a de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Copia de los documentos exigibles en aplicación de las medidas de diligencia debida, durante un periodo de diez años desde la terminación de la relación de negocios o la ejecución de la operación\"</span>. El plazo corre desde la terminación de la relación de negocios o la ejecución de la operación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1544","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Conservación de documentos. Los sujetos obligados conservarán, durante un periodo de diez años desde la ejecución de la operación o la terminación de la relación de negocios:","o":["copia de los documentos de identificación de los clientes y de los titulares reales, con fuerza probatoria.","original o copia con fuerza probatoria de los documentos o registros que acrediten adecuadamente las operaciones, los intervinientes y las relaciones de negocio.","original de los contratos celebrados con los clientes y de las comunicaciones remitidas al Servicio Ejecutivo.","registro de las operaciones sujetas a comunicación sistemática y de los exámenes especiales realizados sobre ellas, sin perjuicio de lo dispuesto en otras disposiciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">original o copia con fuerza probatoria de los documentos o registros que acrediten adecuadamente las operaciones, los intervinientes y las relaciones de negocio</mark></span>El <span class=\"ref-norma\">art. 25.1.b de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Original o copia con fuerza probatoria de los documentos o registros que acrediten adecuadamente las operaciones, los intervinientes en las mismas y las relaciones de negocio, durante un periodo de diez años desde la ejecución de la operación o la terminación de la relación de negocios\"</span>. Se conserva original o copia con fuerza probatoria de los documentos o registros que acrediten operaciones, intervinientes y relaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1535","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Colaboración con la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias y con sus órganos de apoyo. Los sujetos obligados establecerán sistemas que les permitan responder de forma completa y diligente a las solicitudes de información sobre si mantienen o han mantenido relaciones de negocios con determinadas personas a lo largo de los:","o":["cinco años anteriores.","veinte años anteriores.","diez años anteriores.","tres años anteriores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">diez años anteriores</mark></span>El <span class=\"ref-norma\">art. 21.2 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"si mantienen o han mantenido a lo largo de los diez años anteriores relaciones de negocios con determinadas personas físicas o jurídicas y sobre la naturaleza de dichas relaciones\"</span>. El periodo es de diez años, igual que el de conservación de documentos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1910","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Disposición adicional tercera. Registro de Titularidades Reales. La información del Registro de Titularidades Reales se conservará y actualizará durante la vida de las personas jurídicas o entidades o estructuras sin personalidad jurídica, y se mantendrá por un periodo de:","o":["5 años tras su extinción.","15 años tras su extinción, salvo que se disponga otra cosa en la normativa aplicable.","2 años tras su extinción.","10 años tras su extinción."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">10 años tras su extinción</mark></span>El <span class=\"ref-norma\">disposición adicional tercera.3 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"y se mantendrá por un periodo de 10 años tras su extinción\"</span>. Se mantiene diez años tras la extinción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1545","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Conservación de documentos. Los sujetos obligados almacenarán las copias de los documentos de identificación en soportes ópticos, magnéticos o electrónicos que garanticen:","o":["su integridad, la correcta lectura de los datos, la imposibilidad de manipulación y su adecuada conservación y localización.","su autenticidad, la confidencialidad de los datos, la trazabilidad de los accesos y su adecuada destrucción, en los términos que establezca la propia norma.","su integridad, la disponibilidad inmediata de los datos y la posibilidad de rectificación por el cliente.","su autenticidad, la correcta lectura de los datos y su remisión automática al Servicio Ejecutivo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">su integridad, la correcta lectura de los datos, la imposibilidad de manipulación y su adecuada conservación y localización</mark></span>El <span class=\"ref-norma\">art. 25.2 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"o electrónicos que garanticen su integridad, la correcta lectura de los datos, la imposibilidad de manipulación y su adecuada conservación y localización\"</span>. Los soportes deben garantizar integridad, correcta lectura, imposibilidad de manipulación y adecuada conservación y localización. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ÓRGANOS CENTRALIZADOS DE PREVENCIÓN Y EXAMEN EXTERNO arts. 27 y 28 · cuadro del temario","q":[{"i":"2-130","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Órganos centralizados de prevención. Podrá acordarse la constitución de órganos centralizados de prevención de las profesiones colegiadas sujetas a la Ley:","o":["Mediante orden del Ministro de Economía y Empresa.","Mediante real decreto del Consejo de Ministros.","Por acuerdo de los consejos generales de los colegios profesionales.","Mediante resolución de la Secretaría de la Comisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Mediante orden del Ministro de Economía y Empresa</mark></span>Según el <span class=\"ref-norma\">art. 27.1 de la Ley 10/2010</span>: <span class=\"ref-concepto\">\"Mediante orden del Ministro Economía y Empresa podrá acordarse la constitución de órganos\"</span>. Ficha RECUERDA R15. <i>(ficha RECUERDA R15 del temario)</i>"},{"i":"2-ia-1561","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Órganos centralizados de prevención. La constitución de órganos centralizados de prevención de las profesiones colegiadas sujetas a la Ley podrá acordarse:","o":["mediante orden del Ministro de Economía y Empresa.","mediante acuerdo del Consejo de Ministros.","mediante resolución de la Comisión de Prevención del Blanqueo de Capitales.","mediante convenio entre los colegios profesionales y el Servicio Ejecutivo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">mediante orden del Ministro de Economía y Empresa</mark></span>El <span class=\"ref-norma\">art. 27.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Mediante orden del Ministro Economía y Empresa podrá acordarse la constitución de órganos centralizados de prevención de las profesiones colegiadas sujetas a la presente Ley\"</span>. Se constituyen por orden ministerial del titular de Economía. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1562","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Órganos centralizados de prevención. Los órganos centralizados de prevención tendrán por función la intensificación y canalización de la colaboración de las profesiones colegiadas con las autoridades judiciales, policiales y administrativas, sin perjuicio:","o":["de las competencias del Servicio Ejecutivo de la Comisión de Prevención del Blanqueo, salvo que se disponga otra cosa en la normativa aplicable.","del deber de secreto profesional de los abogados y procuradores.","de la supervisión de los colegios profesionales sobre sus colegiados.","de la responsabilidad directa de los profesionales incorporados como sujetos obligados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de la responsabilidad directa de los profesionales incorporados como sujetos obligados</mark></span>El <span class=\"ref-norma\">art. 27.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"sin perjuicio de la responsabilidad directa de los profesionales incorporados como sujetos obligados\"</span>. Los profesionales siguen respondiendo directamente como sujetos obligados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1601","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Órganos centralizados de prevención. Con excepción de los funcionarios que se citan en la Ley, la incorporación de los sujetos obligados a los órganos centralizados de prevención será:","o":["voluntaria.","obligatoria.","obligatoria para los profesionales colegiados que ejerzan por cuenta propia.","voluntaria únicamente para los abogados y procuradores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">voluntaria</mark></span>El <span class=\"ref-norma\">art. 27.3 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"la incorporación de los sujetos obligados a los órganos centralizados de prevención será voluntaria\"</span>. La incorporación es voluntaria; en el caso de los funcionarios (notarios y registradores) es obligatoria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 50 y 51 — Clases de infracciones e infracciones muy graves R19","q":[{"i":"2-52","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Las infracciones a la presente ley se clasificarán en:","o":["Leves, medias y graves.","Muy graves y leves.","Muy graves, graves y leves.","Medias y graves."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Muy graves, graves y leves.</mark></span><span class=\"ref-norma\">Art. 50 · Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo</span>. La respuesta correcta es la C porque el artículo 50 de la Ley 10/2010 establece que «las infracciones administrativas previstas en esta Ley se clasificarán en muy graves, graves y leves»."},{"i":"2-ia-1553","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Procedimientos internos de comunicación de potenciales incumplimientos. La obligación de establecer el procedimiento interno de comunicación de potenciales incumplimientos:","o":["no sustituye la necesaria existencia de mecanismos específicos e independientes de comunicación interna de operaciones sospechosas.","sustituye a los mecanismos de comunicación interna de operaciones sospechosas cuando se integren en el mismo sistema, en los términos que establezca la propia norma.","es exigible únicamente a los sujetos obligados que sean entidades financieras.","no exige adoptar medidas de protección de los empleados que informen de las infracciones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no sustituye la necesaria existencia de mecanismos específicos e independientes de comunicación interna de operaciones sospechosas</mark></span>El <span class=\"ref-norma\">art. 26 bis.3 y 4 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"no sustituye la necesaria existencia de mecanismos específicos e independientes de comunicación interna de operaciones sospechosas de estar vinculadas con el blanqueo de capitales o la financiación del terrorismo por parte de empleados\"</span>. Ambos mecanismos coexisten: el de incumplimientos no sustituye al de comunicación interna de operaciones sospechosas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1760","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Infracciones muy graves. Constituirá infracción muy grave el incumplimiento del deber de comunicación por indicio cuando algún directivo o empleado del sujeto obligado:","o":["hubiera comunicado directamente al Servicio Ejecutivo la existencia de indicios o certeza de relación con el blanqueo.","hubiera puesto de manifiesto internamente la existencia de indicios o certeza de relación con el blanqueo.","hubiera solicitado al órgano de control interno el examen especial de una operación inusual.","hubiera advertido que el cliente aportaba documentación falsa en el momento de la identificación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">hubiera puesto de manifiesto internamente la existencia de indicios o certeza de relación con el blanqueo</mark></span>El <span class=\"ref-norma\">art. 51.1.a de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"cuando algún directivo o empleado del sujeto obligado hubiera puesto de manifiesto internamente la existencia de indicios o la certeza de que un hecho u operación estaba relacionado con el blanqueo de capitales o la financiación del terrorismo\"</span>. Es muy grave cuando algún directivo o empleado puso de manifiesto internamente los indicios o la certeza. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-170","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Infracciones graves. Constituye infracción grave la resistencia u obstrucción a la labor inspectora cuando:","o":["Haya mediado requerimiento del personal actuante expreso y por escrito al respecto.","No haya mediado requerimiento del personal actuante expreso y por escrito al respecto.","Haya mediado requerimiento del Comité Permanente con voluntad deliberadamente rebelde.","Se haya impuesto sanción firme por la misma conducta en los cinco años anteriores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">No haya mediado requerimiento del personal actuante expreso y por escrito al respecto</mark></span>Según el <span class=\"ref-norma\">art. 52.1 y) de la Ley 10/2010</span>: <span class=\"ref-concepto\">\"La resistencia u obstrucción a la labor inspectora cuando no haya mediado requerimiento del personal actuante expreso y por escrito al respecto\"</span>. Con requerimiento expreso y por escrito es muy grave (art. 51.1.d); sin él, grave (art. 52.1.y). <i>(marca EXOF del temario)</i>"},{"i":"2-ia-1436","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Aplicación de las medidas de diligencia debida. Los sujetos obligados deberán estar en condiciones de demostrar a las autoridades competentes que las medidas adoptadas tienen el alcance adecuado en vista del riesgo, mediante un previo análisis de riesgo que en todo caso deberá constar:","o":["en soporte electrónico.","por escrito.","en el manual de procedimientos.","en un informe anual."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por escrito</mark></span>El <span class=\"ref-norma\">art. 7.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"mediante un previo análisis de riesgo que en todo caso deberá constar por escrito\"</span>. El análisis de riesgo previo debe constar por escrito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1440","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Aplicación de las medidas de diligencia debida. La negativa a establecer relaciones de negocio o a ejecutar operaciones, o la terminación de la relación por imposibilidad de aplicar las medidas de diligencia debida, no conllevará ningún tipo de responsabilidad para los sujetos obligados, salvo que:","o":["medie dolo o culpa grave del sujeto obligado.","medie enriquecimiento injusto.","se haya producido un perjuicio económico al cliente.","el cliente hubiera acreditado su identidad documentalmente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">medie enriquecimiento injusto</mark></span>El <span class=\"ref-norma\">art. 7.3 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"no conllevará, salvo que medie enriquecimiento injusto, ningún tipo de responsabilidad para los sujetos obligados\"</span>. La única salvedad es el enriquecimiento injusto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1801","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Infracciones muy graves. Constituirá infracción muy grave la resistencia u obstrucción a la labor inspectora, siempre que medie:","o":["requerimiento del personal actuante expreso y por escrito al respecto.","requerimiento del Servicio Ejecutivo notificado de forma fehaciente, en los términos que establezca la propia norma.","acuerdo del Comité Permanente comunicado al sujeto obligado.","apercibimiento previo del inspector actuante levantado en acta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">requerimiento del personal actuante expreso y por escrito al respecto</mark></span>El <span class=\"ref-norma\">art. 51.1.d de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"La resistencia u obstrucción a la labor inspectora, siempre que medie requerimiento del personal actuante expreso y por escrito al respecto\"</span>. Es muy grave si hubo requerimiento expreso y por escrito del personal actuante; si no lo hubo, es grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1814","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Infracciones graves. Constituye infracción grave la resistencia u obstrucción a la labor inspectora cuando:","o":["se haya producido por primera vez durante la inspección.","no haya impedido la finalización de las actuaciones inspectoras.","haya sido realizada por empleados sin conocimiento de la dirección, salvo que se disponga otra cosa en la normativa aplicable.","no haya mediado requerimiento del personal actuante expreso y por escrito al respecto."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no haya mediado requerimiento del personal actuante expreso y por escrito al respecto</mark></span>El <span class=\"ref-norma\">art. 52.1.y de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"La resistencia u obstrucción a la labor inspectora cuando no haya mediado requerimiento del personal actuante expreso y por escrito al respecto\"</span>. Sin requerimiento expreso y por escrito es grave; con él, muy grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1856","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Procedimiento sancionador y medidas cautelares. Cuando la resolución no acuerde la sanción de amonestación pública, la Secretaría publicará en la página web de la Comisión las sanciones firmes por infracciones muy graves y graves, indicando el tipo y naturaleza de la infracción y la sanción, pero:","o":["identificando únicamente a la entidad responsable de la infracción, sin perjuicio de lo dispuesto en otras disposiciones.","sin identificar a la entidad, persona o personas responsables de la infracción.","sin indicar la sanción impuesta por cada una de las infracciones.","identificando a las personas responsables, pero no a la entidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sin identificar a la entidad, persona o personas responsables de la infracción</mark></span>El <span class=\"ref-norma\">art. 61.6 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"pero sin identificar a la entidad, persona o personas responsables de la infracción\"</span>. La publicación es anónima y permanece disponible cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1111","p":"Ley 19/2003, de 4 de julio, sobre régimen jurídico de los movimientos de capitales y de las transacciones económicas con el exterior. Disposición adicional primera. Modificación de la Ley 19/1993, de 28 de diciembre, sobre determinadas medidas de prevención del blanqueo de capitales. Los sujetos obligados colaborarán con el Servicio Ejecutivo comunicándole, por iniciativa propia, cualquier hecho u operación respecto al que exista indicio o certeza de que está relacionado con el blanqueo de capitales. La comunicación la realizará, en principio:","o":["el representante legal de la entidad ante el Servicio Ejecutivo, conforme al procedimiento que se establezca reglamentariamente.","el responsable de cumplimiento normativo del sujeto obligado.","la persona o personas que los sujetos obligados hubieran designado.","el órgano de control interno que designe el Banco de España."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la persona o personas que los sujetos obligados hubieran designado</mark></span>El <span class=\"ref-norma\">disposición adicional primera (art. 3.4.a de la Ley 19/1993) de la Ley 19/2003</span> dispone: <span class=\"ref-concepto\">\"La comunicación la realizará, en principio, la persona o personas que los sujetos obligados hubieran designado\"</span>. Comunica la persona o personas designadas por el propio sujeto obligado, que también comparecerán en los procedimientos relacionados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1727","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Órganos de apoyo de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias. Entre las funciones del Servicio Ejecutivo de la Comisión figura efectuar recomendaciones a los sujetos obligados orientadas a la mejora de las medidas de control interno y:","o":["formular directamente requerimientos a los sujetos obligados en su ámbito de supervisión.","imponer a los sujetos obligados las medidas correctoras que estime necesarias.","proponer al Comité Permanente la formulación de requerimientos a los sujetos obligados.","aprobar las guías de actuación y orientaciones dirigidas a los sujetos obligados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">proponer al Comité Permanente la formulación de requerimientos a los sujetos obligados</mark></span>El <span class=\"ref-norma\">art. 45.4.h de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Proponer al Comité Permanente la formulación de requerimientos a los sujetos obligados\"</span>. El Servicio Ejecutivo propone; el Comité Permanente formula los requerimientos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1803","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Infracciones muy graves. Constituirá infracción muy grave la comisión de una infracción grave cuando durante los cinco años anteriores hubiera sido impuesta al sujeto obligado:","o":["sanción firme en vía administrativa por cualquier tipo de infracción.","sanción en vía administrativa, aunque estuviera recurrida, por el mismo tipo de infracción.","sanción firme en vía administrativa por el mismo tipo de infracción.","sanción firme en vía administrativa por una infracción de la misma gravedad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">sanción firme en vía administrativa por el mismo tipo de infracción</mark></span>El <span class=\"ref-norma\">art. 51.1.f de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"La comisión de una infracción grave cuando durante los cinco años anteriores hubiera sido impuesta al sujeto obligado sanción firme en vía administrativa por el mismo tipo de infracción\"</span>. Es la reincidencia: sanción firme en vía administrativa por el mismo tipo de infracción en los cinco años anteriores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1802","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Infracciones muy graves. Constituirá infracción muy grave el incumplimiento de la obligación de adoptar las medidas correctoras comunicadas por requerimiento del Comité Permanente cuando concurra:","o":["una reiteración del incumplimiento durante dos ejercicios.","un perjuicio relevante para la estabilidad del sistema financiero.","una falta de colaboración con el Servicio Ejecutivo.","una voluntad deliberadamente rebelde al cumplimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">una voluntad deliberadamente rebelde al cumplimiento</mark></span>El <span class=\"ref-norma\">art. 51.1.e de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"cuando concurra una voluntad deliberadamente rebelde al cumplimiento\"</span>. Si no concurre voluntad deliberadamente rebelde, la infracción es grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1804","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Infracciones muy graves. Constituirá infracción muy grave el incumplimiento de las medidas de suspensión de una transacción acordadas por:","o":["el Comité Permanente de la Comisión a propuesta de la Secretaría de la Comisión, sin perjuicio de lo dispuesto en otras disposiciones.","el Servicio Ejecutivo de la Comisión a requerimiento de una Unidad de Inteligencia Financiera de otro Estado miembro.","la Secretaría de la Comisión a petición del Servicio Ejecutivo de la Comisión.","la autoridad judicial a solicitud del Ministerio Fiscal en un proceso penal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Servicio Ejecutivo de la Comisión a requerimiento de una Unidad de Inteligencia Financiera de otro Estado miembro</mark></span>El <span class=\"ref-norma\">art. 51.1.g de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"El incumplimiento de las medidas de suspensión acordadas por el Servicio Ejecutivo de la Comisión\"</span>. Se trata de las suspensiones acordadas por el Servicio Ejecutivo a requerimiento de una UIF de la Unión Europea. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1805","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Infracciones muy graves. En los términos previstos por los Reglamentos comunitarios que establezcan medidas restrictivas específicas, constituirán infracciones muy graves el incumplimiento:","o":["doloso de la obligación de congelar o bloquear los fondos de personas, entidades o grupos designados.","negligente de la obligación de congelar o bloquear los fondos de personas, entidades o grupos designados.","doloso o negligente de la obligación de comunicar a las autoridades las operaciones con personas designadas.","reiterado de la obligación de congelar o bloquear los fondos de personas, entidades o grupos designados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">doloso de la obligación de congelar o bloquear los fondos de personas, entidades o grupos designados</mark></span>El <span class=\"ref-norma\">art. 51.2 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"El incumplimiento doloso de la obligación de congelar o bloquear los fondos, activos financieros o recursos económicos de personas físicas o jurídicas, entidades o grupos designados\"</span>. Es muy grave el incumplimiento doloso; si no es doloso, será grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1812","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Infracciones graves. Constituye infracción grave el incumplimiento de la obligación de adoptar las medidas correctoras comunicadas por requerimiento del Comité Permanente cuando:","o":["el incumplimiento sea inferior a seis meses.","no concurra una voluntad deliberadamente rebelde al cumplimiento.","las medidas no afecten a la estabilidad de la entidad, sin perjuicio de lo dispuesto en otras disposiciones.","el sujeto obligado haya colaborado con la inspección."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no concurra una voluntad deliberadamente rebelde al cumplimiento</mark></span>El <span class=\"ref-norma\">art. 52.1.w de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"cuando no concurra una voluntad deliberadamente rebelde al cumplimiento\"</span>. Grave si no hay voluntad deliberadamente rebelde; con ella, es muy grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"SANCIONES DE LA LEY 10/2010 arts. 56, 57 y 58 · cuadros del temario · ¡ojo con la única que «podrá»!","q":[{"i":"2-174","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Sanciones por infracciones muy graves. Por la comisión de infracciones muy graves se podrá imponer una multa cuyo importe mínimo será de:","o":["60.000 euros.","150.000 euros.","100.000 euros.","300.000 euros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">150.000 euros</mark></span>Según el <span class=\"ref-norma\">art. 56.1 a) de la Ley 10/2010</span>: <span class=\"ref-concepto\">\"Multa cuyo importe mínimo será de 150.000 euros\"</span>. El máximo es la mayor de estas cifras: 10 % del volumen de negocios anual, duplo del contenido económico, quíntuplo de los beneficios o 10.000.000 euros. <i>(marca EXOF del temario)</i>"},{"i":"2-ia-1822","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Sanciones por infracciones muy graves. Por la comisión de infracciones muy graves se podrá imponer una multa cuyo importe mínimo será de:","o":["60.000 euros.","600.000 euros, salvo que se disponga otra cosa en la normativa aplicable.","100.000 euros.","150.000 euros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">150.000 euros</mark></span>El <span class=\"ref-norma\">art. 56.1.a de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Multa cuyo importe mínimo será de 150.000 euros\"</span>. El mínimo es 150.000 euros (60.000 en las graves). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1823","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Sanciones por infracciones muy graves. El importe máximo de la multa por infracciones muy graves ascenderá hasta la mayor de las siguientes cifras: el 10 por ciento del volumen de negocios anual total, el duplo del contenido económico de la operación, el quíntuplo de los beneficios derivados de la infracción, cuando puedan determinarse, o:","o":["5.000.000 de euros.","15.000.000 de euros, conforme al procedimiento que se establezca reglamentariamente.","10.000.000 de euros.","1.000.000 de euros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">10.000.000 de euros</mark></span>El <span class=\"ref-norma\">art. 56.1.a de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"o 10.000.000 euros\"</span>. Tope fijo de 10.000.000 de euros (5.000.000 en las graves). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1824","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Sanciones por infracciones muy graves. Por infracciones muy graves, la multa es obligatoria en todo caso y se impondrá simultáneamente con alguna de las siguientes sanciones:","o":["amonestación pública o privada, o suspensión temporal de la autorización administrativa para operar.","amonestación pública, o suspensión temporal o revocación de la autorización administrativa para operar.","amonestación privada, o suspensión temporal o revocación de la autorización administrativa para operar, sin perjuicio de lo dispuesto en otras disposiciones.","amonestación pública, o separación del cargo con inhabilitación de los administradores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">amonestación pública, o suspensión temporal o revocación de la autorización administrativa para operar</mark></span>El <span class=\"ref-norma\">art. 56.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"La sanción prevista en la letra a), que ha de ser obligatoria en todo caso, se impondrá simultáneamente con alguna de las previstas en las letras b) o c)\"</span>. En las muy graves la amonestación es pública (no privada), y cabe suspensión temporal o revocación de la autorización. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1825","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Sanciones por infracciones muy graves. Además de la sanción al sujeto obligado por infracciones muy graves, a quienes ejerciendo cargos de administración o dirección fueran responsables se les podrá imponer una multa a cada uno de ellos por importe de:","o":["entre 60.000 y 10.000.000 de euros.","entre 3.000 y 5.000.000 de euros.","entre 150.000 y 10.000.000 de euros.","entre 60.000 y 5.000.000 de euros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">entre 60.000 y 10.000.000 de euros</mark></span>El <span class=\"ref-norma\">art. 56.3.a de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Multa a cada uno de ellos por importe de entre 60.000 y 10.000.000 euros\"</span>. En las muy graves, de 60.000 a 10.000.000 de euros; en las graves, de 3.000 a 5.000.000. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1827","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Sanciones por infracciones muy graves. En todos los casos de infracciones muy graves, las sanciones impuestas irán acompañadas de un requerimiento al infractor para que:","o":["subsane el incumplimiento en el plazo de seis meses.","publique la sanción en su página web durante cinco años.","ponga fin a su conducta y se abstenga de repetirla.","adopte un plan de cumplimiento aprobado por la Comisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">ponga fin a su conducta y se abstenga de repetirla</mark></span>El <span class=\"ref-norma\">art. 56.4 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"las sanciones impuestas irán acompañadas de un requerimiento al infractor para que ponga fin a su conducta y se abstenga de repetirla\"</span>. El requerimiento es para poner fin a la conducta y abstenerse de repetirla; en las leves es facultativo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1828","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Sanciones por infracciones muy graves. Acordada la imposición de una sanción de amonestación pública, cuando se determine que aquélla pueda perjudicar una investigación en marcha o poner en peligro la estabilidad de los mercados financieros, la autoridad competente para resolver podrá:","o":["sustituirla por una amonestación privada o por una multa de menor cuantía.","retrasar la publicación o acordar la no publicación de la sanción de forma definitiva.","suspender la ejecución de la sanción hasta la conclusión de la investigación.","publicar la sanción sin identificar a la entidad ni a las personas responsables, sin perjuicio de lo dispuesto en otras disposiciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">retrasar la publicación o acordar la no publicación de la sanción de forma definitiva</mark></span>El <span class=\"ref-norma\">art. 56.5 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"la autoridad competente para resolver podrá: a) retrasar la publicación hasta el momento en que cesen los motivos que justificaron la suspensión\"</span>. Puede retrasar la publicación o, si la estabilidad de los mercados no puede garantizarse, no publicarla definitivamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"GRADUACIÓN DE LAS SANCIONES art. 59 · cuadros del temario ·","q":[{"i":"2-108","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Graduación de las sanciones. Entre las circunstancias para graduar las sanciones se encuentran las sanciones firmes en vía administrativa por infracciones de distinto tipo impuestas al sujeto obligado con arreglo a esta ley:","o":["En los últimos tres años.","En los últimos diez años.","En los últimos cinco años.","En los últimos dos años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En los últimos cinco años</mark></span>Según el <span class=\"ref-norma\">art. 59.1 de la Ley 10/2010</span>: <span class=\"ref-concepto\">\"Las sanciones firmes en vía administrativa por infracciones de distinto tipo impuestas al sujeto obligado en los últimos cinco años con arreglo a esta ley\"</span>. Cuentan las sanciones firmes de los últimos cinco años. <i>(marca EXOF del temario)</i>"},{"i":"2-109","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Graduación de las sanciones. En todo caso, la sanción se graduará de modo que:","o":["El importe de la multa no supere el beneficio obtenido por el infractor como consecuencia de la infracción.","La comisión de las infracciones no resulte más beneficiosa para el infractor que el cumplimiento de las normas infringidas.","La sanción sea proporcionada a la capacidad económica del sujeto obligado, con independencia del beneficio obtenido.","La sanción no pueda superar en ningún caso el doble del contenido económico de la operación afectada por el incumplimiento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La comisión de las infracciones no resulte más beneficiosa para el infractor que el cumplimiento de las normas infringidas</mark></span>Según el <span class=\"ref-norma\">art. 59.1 de la Ley 10/2010</span>: <span class=\"ref-concepto\">\"En todo caso, se graduará la sanción de modo que la comisión de las infracciones no resulte más beneficiosa para el infractor que el cumplimiento de las normas infringidas\"</span>. Regla general de graduación: infringir nunca debe salir más rentable que cumplir. <i>(marca EXOF del temario)</i>"},{"i":"2-ia-1836","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Graduación de las sanciones. Las sanciones se graduarán atendiendo, entre otras, a la cuantía de las operaciones afectadas, los beneficios obtenidos, la circunstancia de haber procedido o no a la subsanación por propia iniciativa y las sanciones firmes en vía administrativa por infracciones de distinto tipo impuestas al sujeto obligado en los últimos:","o":["tres años, sin perjuicio de lo dispuesto en otras disposiciones.","cinco años.","diez años.","dos años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cinco años</mark></span>El <span class=\"ref-norma\">art. 59.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Las sanciones firmes en vía administrativa por infracciones de distinto tipo impuestas al sujeto obligado en los últimos cinco años con arreglo a esta ley\"</span>. Se tienen en cuenta las sanciones firmes por infracciones de distinto tipo de los últimos cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1837","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Graduación de las sanciones. En todo caso, la sanción se graduará de modo que la comisión de las infracciones:","o":["no resulte más beneficiosa para el infractor que el cumplimiento de las normas infringidas.","no resulte más gravosa para el infractor que las consecuencias económicas de su conducta, en los términos que establezca la propia norma.","no suponga la desaparición del sujeto obligado ni su exclusión del mercado.","sea proporcionada a la capacidad económica del inculpado en el momento de la resolución."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no resulte más beneficiosa para el infractor que el cumplimiento de las normas infringidas</mark></span>El <span class=\"ref-norma\">art. 59.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"se graduará la sanción de modo que la comisión de las infracciones no resulte más beneficiosa para el infractor que el cumplimiento de las normas infringidas\"</span>. La sanción nunca debe resultar más beneficiosa para el infractor que cumplir. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1838","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Graduación de las sanciones. Para determinar la sanción aplicable de entre las previstas para los administradores y directivos, se tomarán en consideración, entre otras circunstancias, la conducta anterior del interesado, la capacidad económica cuando la sanción sea multa y:","o":["la antigüedad del interesado en el cargo de administración o dirección.","el volumen de negocios anual del sujeto obligado en el último ejercicio.","la participación del interesado en el capital del sujeto obligado.","el carácter de la representación que el interesado ostente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el carácter de la representación que el interesado ostente</mark></span>El <span class=\"ref-norma\">art. 59.2 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"El carácter de la representación que el interesado ostente\"</span>. Es una circunstancia propia de la graduación individual de administradores y directivos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1839","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Graduación de las sanciones. Para determinar la sanción aplicable por incumplimiento de la obligación de declaración de movimientos de medios de pago se considerará como agravante la notoria cuantía del movimiento, considerándose en todo caso como tal aquélla que:","o":["triplique el umbral de declaración.","supere los 100.000 euros.","duplique el umbral de declaración.","exceda de 50.000 euros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">duplique el umbral de declaración</mark></span>El <span class=\"ref-norma\">art. 59.3.a de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"La notoria cuantía del movimiento, considerándose en todo caso como tal aquélla que duplique el umbral de declaración\"</span>. La cuantía notoria es la que duplica el umbral de declaración. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1840","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Graduación de las sanciones. Entre los agravantes para graduar la sanción por incumplimiento de la obligación de declaración figuran las sanciones firmes en vía administrativa por incumplimiento de dicha obligación impuestas al interesado en los últimos:","o":["tres años, sin perjuicio de lo dispuesto en otras disposiciones.","cinco años.","dos años.","diez años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cinco años</mark></span>El <span class=\"ref-norma\">art. 59.3.e de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Las sanciones firmes en vía administrativa por incumplimiento de la obligación de declaración impuestas al interesado en los últimos cinco años\"</span>. Se computan los últimos cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 60 y 61 — Prescripción y procedimiento sancionador R21","q":[{"i":"2-ia-1833","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Sanciones por infracciones graves. Entre las sanciones aplicables a quienes ejerzan cargos de administración o dirección responsables de infracciones graves figura la separación del cargo, con inhabilitación por un plazo máximo de:","o":["cinco años.","diez años, en los términos que establezca la propia norma.","tres años.","dos años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cinco años</mark></span>El <span class=\"ref-norma\">art. 57.2.d de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Separación del cargo, con inhabilitación para ejercer cargos de administración o dirección en cualquier entidad de las sujetas a esta ley por un plazo máximo de cinco años\"</span>. En las graves la inhabilitación máxima es de cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1855","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Procedimiento sancionador y medidas cautelares. La sanción de amonestación pública, una vez sea firme en vía administrativa, será publicada en el «Boletín Oficial del Estado» y en la página web de la Comisión, donde permanecerá disponible durante el plazo de:","o":["tres años, conforme al procedimiento que se establezca reglamentariamente.","diez años.","cinco años.","un año."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cinco años</mark></span>El <span class=\"ref-norma\">art. 61.5 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"siendo en todo caso publicada en el «Boletín Oficial del Estado» y en la página web de la Comisión, donde permanecerá disponible durante el plazo de cinco años\"</span>. La publicación se mantiene cinco años; la ejecución de las resoluciones firmes corresponde a la Secretaría. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1930","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Disposición transitoria séptima. Aplicación de las medidas de diligencia debida a los clientes existentes. Los sujetos obligados aplicarán a todos sus clientes existentes las medidas de diligencia debida del capítulo II en un plazo máximo, contado desde la entrada en vigor de la Ley, de:","o":["tres años, salvo que se disponga otra cosa en la normativa aplicable.","dos años.","diez años.","cinco años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cinco años</mark></span>El <span class=\"ref-norma\">disposición transitoria séptima de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"los sujetos obligados aplicarán a todos sus clientes existentes las medidas de diligencia debida establecidas en el Capítulo II en un plazo máximo de cinco años\"</span>. El plazo máximo es de cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1841","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Prescripción de las infracciones y de las sanciones. En las infracciones derivadas de una actividad continuada, la fecha inicial del cómputo del plazo de prescripción será:","o":["la de la finalización de la actividad o la del último acto con el que la infracción se consume.","la del primer acto con el que la infracción se haya consumado.","la de la notificación de la primera actuación de la Comisión.","la del descubrimiento de la actividad por el Servicio Ejecutivo, en los términos que establezca la propia norma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la de la finalización de la actividad o la del último acto con el que la infracción se consume</mark></span>El <span class=\"ref-norma\">art. 60.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"En las infracciones derivadas de una actividad continuada, la fecha inicial del cómputo será la de la finalización de la actividad o la del último acto con el que la infracción se consume\"</span>. En las infracciones continuadas el cómputo empieza al finalizar la actividad o con el último acto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-110","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Prescripción de las infracciones y de las sanciones. En el caso de incumplimiento de las obligaciones de diligencia debida, el plazo de prescripción de la infracción se contará desde:","o":["La fecha de terminación de la relación de negocios.","La fecha de la última operación realizada por el cliente.","La fecha en que se inició la relación de negocios.","La fecha en que la Comisión tuvo conocimiento formal de los hechos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La fecha de terminación de la relación de negocios</mark></span>Según el <span class=\"ref-norma\">art. 60.1 de la Ley 10/2010</span>: <span class=\"ref-concepto\">\"En el caso de incumplimiento de las obligaciones de diligencia debida el plazo de prescripción se contará desde la fecha de terminación de la relación de negocios\"</span>. Diligencia debida: desde que termina la relación de negocios; conservación de documentos: desde que expira el plazo del art. 25. <i>(marca EXOF del temario)</i>"},{"i":"2-ia-1842","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Prescripción de las infracciones y de las sanciones. En el caso de incumplimiento de las obligaciones de diligencia debida, el plazo de prescripción de las infracciones se contará desde:","o":["la fecha de establecimiento de la relación de negocios.","la fecha de la última operación realizada por el cliente.","la fecha de conclusión de las actuaciones de inspección.","la fecha de terminación de la relación de negocios."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la fecha de terminación de la relación de negocios</mark></span>El <span class=\"ref-norma\">art. 60.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"En el caso de incumplimiento de las obligaciones de diligencia debida el plazo de prescripción se contará desde la fecha de terminación de la relación de negocios\"</span>. Se cuenta desde la terminación de la relación de negocios; en la conservación de documentos, desde la expiración del plazo de conservación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1844","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Prescripción de las infracciones y de las sanciones. Las sanciones que se impongan conforme a la Ley prescribirán a los tres años en caso de infracciones muy graves, a los dos años en caso de infracciones graves y al año en caso de infracciones leves, contados desde:","o":["la fecha en que la resolución sancionadora sea firme en vía administrativa.","la fecha de notificación de la resolución sancionadora.","la fecha de la comisión de la infracción.","la fecha de inicio del procedimiento sancionador."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la fecha de notificación de la resolución sancionadora</mark></span>El <span class=\"ref-norma\">art. 60.2 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"contados desde la fecha de notificación de la resolución sancionadora\"</span>. Las sanciones prescriben a los 3, 2 y 1 años desde la notificación de la resolución sancionadora. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1515","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Personas con responsabilidad pública. Cuando las personas con responsabilidad pública hayan dejado de desempeñar sus funciones, los sujetos obligados continuarán aplicando las medidas reforzadas por un periodo de:","o":["un año.","cinco años.","dos años.","diez años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">dos años</mark></span>El <span class=\"ref-norma\">art. 14.9 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"las medidas previstas en este artículo por un periodo de dos años\"</span>. Son dos años; después se aplican medidas adecuadas en función del riesgo hasta que se determine que ya no representa un riesgo específico derivado de su antigua condición. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-111","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Prescripción de las infracciones y de las sanciones. Las sanciones que se impongan conforme a la Ley de prevención del blanqueo de capitales prescribirán:","o":["A los cinco años las muy graves, a los cuatro años las graves y a los tres años las leves, contados desde la firmeza de la resolución sancionadora.","A los cinco años las muy graves y graves, y a los dos años las leves, contados desde la fecha en que se cometió la infracción.","A los tres años las muy graves, a los dos años las graves y al año las leves, contados desde la firmeza de la resolución sancionadora.","A los tres años las muy graves, a los dos años las graves y al año las leves, contados desde la notificación de la resolución sancionadora."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A los tres años las muy graves, a los dos años las graves y al año las leves, contados desde la notificación de la resolución sancionadora</mark></span>Según el <span class=\"ref-norma\">art. 60.2 de la Ley 10/2010</span>: <span class=\"ref-concepto\">\"prescribirán a los tres años en caso de infracciones muy graves, a los dos años en caso de infracciones graves, y al año en caso de infracciones leves, contados desde la fecha de notificación de la resolución sancionadora\"</span>. Sanciones: 3 / 2 / 1 años desde la notificación. No confundir con las infracciones (5 / 5 / 2 años). <i>(marca EXOF del temario)</i>"},{"i":"2-136","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Prescripción de las infracciones y de las sanciones. Las infracciones muy graves y graves de la Ley de prevención del blanqueo de capitales prescribirán:","o":["A los cinco años, y las leves al año, contados desde la fecha en que la infracción hubiera sido descubierta.","A los tres años, y las leves a los dos años, contados desde la fecha en que la infracción hubiera sido cometida.","A los cinco años, y las leves a los dos años, contados desde la fecha en que la infracción hubiera sido cometida.","A los cuatro años, y las leves a los dos años, contados desde la fecha de notificación del acuerdo de incoación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A los cinco años, y las leves a los dos años, contados desde la fecha en que la infracción hubiera sido cometida</mark></span>Según el <span class=\"ref-norma\">art. 60.1 de la Ley 10/2010</span>: <span class=\"ref-concepto\">\"Las infracciones muy graves y graves prescribirán a los cinco años, y las leves a los dos años, contados desde la fecha en que la infracción hubiera sido cometida\"</span>. Ficha RECUERDA R21 (y marca EXOF del temario). <i>(ficha RECUERDA R21 del temario)</i>"},{"i":"2-ia-1607","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Examen externo. El informe de examen externo estará en todo caso a disposición de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias o de sus órganos de apoyo durante:","o":["los diez años siguientes a la fecha de emisión.","los tres años siguientes a la fecha de emisión.","los cinco años siguientes a la fecha de emisión.","los cinco años siguientes a la elevación al órgano de administración."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los cinco años siguientes a la fecha de emisión</mark></span>El <span class=\"ref-norma\">art. 28.3 y 4 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"durante los cinco años siguientes a la fecha de emisión\"</span>. Se conserva a disposición durante cinco años desde la emisión; la obligación no es exigible a empresarios o profesionales individuales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1943","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Disposición final séptima. Entrada en vigor. La Ley 10/2010 entró en vigor el día siguiente al de su publicación en el «Boletín Oficial del Estado», con la excepción de las obligaciones de almacenar las copias de los documentos de identificación en soportes ópticos, magnéticos o electrónicos y de las relativas al envío de dinero, que entrarían en vigor, respectivamente, a los:","o":["un año y dos años de la publicación de la Ley.","seis meses y un año de la publicación de la Ley.","dos años y un año de la publicación de la Ley.","dos años y dos años de la publicación de la Ley."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">dos años y un año de la publicación de la Ley</mark></span>El <span class=\"ref-norma\">disposición final séptima de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"que entrarán en vigor a los dos años y un año, respectivamente, de la publicación de la presente Ley\"</span>. El almacenamiento de copias en soportes (art. 25.2) a los dos años y el envío de dinero (art. 41) al año. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1845","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Procedimiento sancionador y medidas cautelares. La incoación y, en su caso, el sobreseimiento de los procedimientos sancionadores por la comisión de las infracciones de la Ley corresponderá:","o":["al Comité Permanente, a propuesta de la Secretaría de la Comisión.","a la Secretaría de la Comisión, a propuesta del Servicio Ejecutivo.","al Pleno de la Comisión, a propuesta del Comité Permanente.","al Servicio Ejecutivo, a propuesta de la Secretaría de la Comisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al Comité Permanente, a propuesta de la Secretaría de la Comisión</mark></span>El <span class=\"ref-norma\">art. 61.1 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"corresponderá al Comité Permanente, a propuesta de la Secretaría de la Comisión\"</span>. Incoa el Comité Permanente a propuesta de la Secretaría; en las infracciones de la obligación de declarar medios de pago incoa la Secretaría. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1846","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Procedimiento sancionador y medidas cautelares. La instrucción de los procedimientos sancionadores por infracciones de la Ley corresponderá a:","o":["el Servicio Ejecutivo de la Comisión.","el Comité Permanente de la Comisión.","la Dirección General del Tesoro y Política Financiera.","la Secretaría de la Comisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la Secretaría de la Comisión</mark></span>El <span class=\"ref-norma\">art. 61.2 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"La instrucción de los procedimientos sancionadores a que hubiera lugar por la comisión de infracciones previstas en esta ley corresponderá a la Secretaría de la Comisión\"</span>. Instruye la Secretaría de la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1847","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Procedimiento sancionador y medidas cautelares. El órgano competente para la incoación del procedimiento sancionador podrá acordar, al tiempo de iniciarse el procedimiento o durante su tramitación:","o":["la suspensión provisional de la actividad del sujeto obligado.","la intervención de los fondos y activos del presunto infractor, conforme al procedimiento que se establezca reglamentariamente.","la constitución de garantía suficiente para hacer frente a las responsabilidades a que hubiera lugar.","el cierre cautelar de las oficinas del sujeto obligado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la constitución de garantía suficiente para hacer frente a las responsabilidades a que hubiera lugar</mark></span>El <span class=\"ref-norma\">art. 61.2 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"podrá acordar, al tiempo de iniciarse el procedimiento o durante su tramitación, la constitución de garantía suficiente para hacer frente a las responsabilidades a que hubiera lugar\"</span>. La medida cautelar prevista es la constitución de garantía suficiente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1848","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Procedimiento sancionador y medidas cautelares. Será competente para imponer las sanciones por infracciones muy graves:","o":["el Ministro de Economía y Hacienda, a propuesta de la Comisión.","el Consejo de Ministros, a propuesta del Ministro de Economía y Hacienda.","el Director General del Tesoro y Política Financiera, a propuesta del instructor.","el Comité Permanente, a propuesta de la Secretaría de la Comisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Consejo de Ministros, a propuesta del Ministro de Economía y Hacienda</mark></span>El <span class=\"ref-norma\">art. 61.3 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Será competente para imponer las sanciones por infracciones muy graves el Consejo de Ministros, a propuesta del Ministro de Economía y Hacienda\"</span>. Muy graves: Consejo de Ministros; graves: Ministro; leves: Director General del Tesoro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1850","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Procedimiento sancionador y medidas cautelares. Será competente para imponer las sanciones por infracciones leves:","o":["el Secretario de la Comisión, a propuesta del instructor.","el Ministro de Economía y Hacienda, a propuesta del Comité Permanente, salvo que se disponga otra cosa en la normativa aplicable.","el Comité Permanente, a propuesta de la Secretaría de la Comisión.","el Director General del Tesoro y Política Financiera, a propuesta del instructor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el Director General del Tesoro y Política Financiera, a propuesta del instructor</mark></span>El <span class=\"ref-norma\">art. 61.3 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"Será competente para imponer las sanciones por infracciones leves el Director General del Tesoro y Política Financiera, a propuesta del instructor\"</span>. Las leves las impone el Director General del Tesoro y Política Financiera a propuesta del instructor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1852","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Procedimiento sancionador y medidas cautelares. La competencia para resolver los procedimientos sancionadores por incumplimiento de la obligación de declaración de medios de pago corresponderá, a propuesta del instructor y previo informe del Servicio Ejecutivo:","o":["al Ministro de Economía y Hacienda, cuyas resoluciones pondrán fin a la vía administrativa, sin perjuicio de lo dispuesto en otras disposiciones.","al Director General del Tesoro y Política Financiera, cuyas resoluciones pondrán fin a la vía administrativa.","a la Secretaría de la Comisión, cuyas resoluciones podrán recurrirse en alzada.","al Comité Permanente, cuyas resoluciones podrán recurrirse en alzada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al Director General del Tesoro y Política Financiera, cuyas resoluciones pondrán fin a la vía administrativa</mark></span>El <span class=\"ref-norma\">art. 61.3 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"corresponderá, a propuesta del instructor y previo informe del Servicio Ejecutivo de la Comisión, al Director General del Tesoro y Política Financiera, cuyas resoluciones pondrán fin a la vía administrativa\"</span>. Resuelve el Director General del Tesoro y Política Financiera, y su resolución pone fin a la vía administrativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-21","p":"Ley 10/2010 Prevención del blanqueo de capitales y financiación del terrorismo. En los procedimientos sancionadores instruidos por la Secretaría de la Comisión el plazo máximo para resolver el procedimiento y notificar la resolución será de:","o":["Seis años.","Un año.","Seis meses.","Tres meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Un año.</mark></span><span class=\"ref-norma\">Art. 61.4 · Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo</span>. El art. 61.4 de la Ley 10/2010 dispone: \"En los procedimientos sancionadores instruidos por la Secretaría de la Comisión el plazo máximo para resolver el procedimiento y notificar la resolución será de un año a contar desde la fecha de notificación del acuerdo de incoación...\""},{"i":"2-ia-1903","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Disposición adicional primera. Registro de prestadores de servicios a sociedades y fideicomisos. Las personas físicas o jurídicas que a la fecha de entrada en vigor de la disposición estuvieran realizando actividades de prestación de servicios a sociedades y no constaren inscritas deberán inscribirse en el plazo de:","o":["seis meses.","dos años.","un año.","tres meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un año</mark></span>El <span class=\"ref-norma\">disposición adicional primera.4 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"y no constaren inscritas, deberán, en el plazo de un año, inscribirse\"</span>. El plazo es de un año; los ya inscritos deben presentar, en el mismo plazo, una manifestación de estar sometidos como sujetos obligados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1851","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Procedimiento sancionador y medidas cautelares. Cuando el inculpado sea una entidad financiera o precise de autorización administrativa para operar, será preceptivo para la imposición de sanciones por infracciones graves o muy graves solicitar de la institución u órgano responsable de su supervisión informe sobre:","o":["la procedencia de revocar la autorización administrativa de la entidad.","la existencia de infracciones previas cometidas por la entidad en otros Estados, conforme al procedimiento que se establezca reglamentariamente.","la posible incidencia de la sanción propuesta sobre la estabilidad de la entidad.","la solvencia de la entidad para hacer frente a la multa propuesta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la posible incidencia de la sanción propuesta sobre la estabilidad de la entidad</mark></span>El <span class=\"ref-norma\">art. 61.3 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"solicitar de la institución u órgano administrativo responsable de su supervisión informe sobre la posible incidencia de la sanción o sanciones propuestas sobre la estabilidad de la entidad objeto del procedimiento\"</span>. El informe del supervisor versa sobre la posible incidencia de la sanción en la estabilidad de la entidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1854","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Procedimiento sancionador y medidas cautelares. El transcurso de los plazos máximos para resolver el procedimiento sancionador determinará:","o":["el archivo del procedimiento y la prescripción de la infracción.","la estimación por silencio de las alegaciones del interesado.","la suspensión del procedimiento hasta que se dicte resolución expresa, salvo que se disponga otra cosa en la normativa aplicable.","la caducidad del procedimiento, debiendo dictarse nuevo acuerdo de incoación en tanto no haya prescrito la infracción."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la caducidad del procedimiento, debiendo dictarse nuevo acuerdo de incoación en tanto no haya prescrito la infracción</mark></span>El <span class=\"ref-norma\">art. 61.4 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"determinará la caducidad del procedimiento administrativo sancionador, debiendo procederse a dictar nuevo acuerdo de incoación en tanto no haya prescrito la infracción\"</span>. Produce caducidad, pero puede incoarse de nuevo mientras no haya prescrito la infracción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-1857","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Procedimiento sancionador y medidas cautelares. La Secretaría de la Comisión informará a la Autoridad Bancaria Europea de todas las sanciones impuestas a las entidades de crédito y financieras, incluido:","o":["cualquier recurso que se haya podido interponer contra las mismas y su resultado.","el informe de supervisión del órgano competente sobre la estabilidad de la entidad.","el plan de acción correctora presentado por la entidad sancionada.","la identidad de los administradores y directivos sancionados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cualquier recurso que se haya podido interponer contra las mismas y su resultado</mark></span>El <span class=\"ref-norma\">art. 61.7 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"incluido cualquier recurso que se haya podido interponer contra las mismas y su resultado\"</span>. Debe comunicar las sanciones, los recursos interpuestos y su resultado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 61 — Ejecución de las resoluciones sancionadoras R22","q":[{"i":"2-137","p":"Ley 10/2010, de prevención del blanqueo de capitales y de la financiación del terrorismo. Procedimiento sancionador. La ejecución de las resoluciones sancionadoras firmes en vía administrativa corresponderá a:","o":["El Servicio Ejecutivo de la Comisión.","La Secretaría de la Comisión.","El Comité Permanente de la Comisión.","La Dirección General del Tesoro."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Secretaría de la Comisión</mark></span>Según el <span class=\"ref-norma\">art. 61.6 de la Ley 10/2010</span>: <span class=\"ref-concepto\">\"la Secretaría de la Comisión\"</span>. Ficha RECUERDA R22. <i>(ficha RECUERDA R22 del temario)</i>"}]},{"a":"EL DELITO SERÁ DE CARÁCTER TRANSNACIONAL SI: Convención de Palermo · art. 3.2 · cuadro del temario ·","q":[{"i":"2-177","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Ámbito de aplicación. Según la Convención de Palermo, el delito será de carácter transnacional si (señale la INCORRECTA):","o":["Se comete en más de un Estado.","Se comete dentro de un solo Estado, pero una parte sustancial de su preparación, planificación, dirección o control se realiza en otro Estado.","Se comete en un solo Estado y entraña la participación de un grupo delictivo organizado que actúa solo en ese Estado.","Se comete en un solo Estado, pero tiene efectos sustanciales en otro Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Se comete en un solo Estado y entraña la participación de un grupo delictivo organizado que actúa solo en ese Estado</mark></span>Según el <span class=\"ref-norma\">art. 3.2 de la Convención de Palermo</span>: <span class=\"ref-concepto\">\"se comete en más de un Estado; b) se comete dentro de un solo Estado pero una parte sustancial de su preparación, planificación, dirección o control se realiza en otro Estado; c) se comete dentro de un solo Estado pero entraña la participación de un grupo delictivo organizado que realiza actividades delictivas en más de un Estado\"</span>. Si el grupo delictivo organizado actúa en un solo Estado, el delito no es transnacional; hace falta que realice actividades delictivas en más de un Estado. <i>(marca EXOF del temario)</i>"},{"i":"2-178","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Ámbito de aplicación. La Convención de Palermo se aplicará a la prevención, investigación y enjuiciamiento de los delitos tipificados con arreglo a sus artículos 5, 6, 8 y 23 y de los delitos graves, cuando esos delitos sean de carácter transnacional y:","o":["Se cometan en el territorio de al menos tres Estados Parte.","Entrañen la participación de un grupo delictivo organizado.","Hayan causado un perjuicio económico superior a un millón de euros.","Hayan sido cometidos por más de cinco personas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Entrañen la participación de un grupo delictivo organizado</mark></span>Según el <span class=\"ref-norma\">art. 3.1 de la Convención de Palermo</span>: <span class=\"ref-concepto\">\"cuando esos delitos sean de carácter transnacional y entrañen la participación de un grupo delictivo organizado\"</span>. Son dos requisitos acumulados: carácter transnacional y participación de un grupo delictivo organizado. <i>(marca EXOF del temario)</i>"},{"i":"2-ia-2009","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Ámbito de aplicación. Salvo disposición en contrario, la Convención se aplicará a la prevención, investigación y enjuiciamiento de los delitos tipificados en ella y de los delitos graves, cuando esos delitos sean de carácter transnacional y:","o":["entrañen la participación de un grupo delictivo organizado.","afecten a los intereses de al menos tres Estados Parte.","se cometan con un propósito de obtención de beneficio económico.","hayan sido cometidos por personas jurídicas o grupos terroristas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">entrañen la participación de un grupo delictivo organizado</mark></span>El <span class=\"ref-norma\">art. 3.1 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"cuando esos delitos sean de carácter transnacional y entrañen la participación de un grupo delictivo organizado\"</span>. Se exige carácter transnacional y participación de un grupo delictivo organizado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2010","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Ámbito de aplicación. Un delito será de carácter transnacional si se comete dentro de un solo Estado pero:","o":["una parte de sus autores o víctimas tienen la nacionalidad de otro Estado, salvo que se disponga otra cosa en la normativa aplicable.","una parte de los bienes obtenidos se encuentra depositada en otro Estado.","una parte de las pruebas de su comisión se encuentra en otro Estado.","una parte sustancial de su preparación, planificación, dirección o control se realiza en otro Estado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">una parte sustancial de su preparación, planificación, dirección o control se realiza en otro Estado</mark></span>El <span class=\"ref-norma\">art. 3.2.b de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"Se comete dentro de un solo Estado pero una parte sustancial de su preparación, planificación, dirección o control se realiza en otro Estado\"</span>. Basta con que una parte sustancial de la preparación, planificación, dirección o control se realice en otro Estado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2011","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Ámbito de aplicación. Un delito será de carácter transnacional si se comete dentro de un solo Estado pero entraña la participación de un grupo delictivo organizado que:","o":["tiene miembros de más de una nacionalidad.","cuenta con una estructura jerárquica desarrollada.","realiza actividades delictivas en más de un Estado.","obtiene beneficios económicos de origen internacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">realiza actividades delictivas en más de un Estado</mark></span>El <span class=\"ref-norma\">art. 3.2.c de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"entraña la participación de un grupo delictivo organizado que realiza actividades delictivas en más de un Estado\"</span>. Es transnacional si el grupo realiza actividades delictivas en más de un Estado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2012","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Ámbito de aplicación. Un delito será de carácter transnacional si se comete en un solo Estado pero:","o":["tiene como víctima a un nacional de otro Estado.","tiene efectos sustanciales en otro Estado.","se difunde a través de medios de comunicación internacionales.","se financia con fondos procedentes de otro Estado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tiene efectos sustanciales en otro Estado</mark></span>El <span class=\"ref-norma\">art. 3.2.d de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"Se comete en un solo Estado pero tiene efectos sustanciales en otro Estado\"</span>. El cuarto supuesto exige efectos sustanciales en otro Estado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 16 y 17 — Extradición y traslado de condenados ✱","q":[{"i":"2-ia-1518","p":"Ley 10/2010, de 28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo. Productos u operaciones propicios al anonimato y nuevos desarrollos tecnológicos. Los sujetos obligados prestarán especial atención a todo riesgo de blanqueo de capitales o de financiación del terrorismo que pueda derivarse de productos u operaciones propicias al anonimato, o de nuevos desarrollos tecnológicos. En tales casos efectuarán un análisis específico de los posibles riesgos, que deberá:","o":["comunicarse al Servicio Ejecutivo antes del lanzamiento del producto.","ser auditado anualmente por un experto externo independiente.","incorporarse al manual de prevención y ser aprobado por el órgano de control interno.","documentarse y estar a disposición de las autoridades competentes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">documentarse y estar a disposición de las autoridades competentes</mark></span>El <span class=\"ref-norma\">art. 16 de la Ley 10/2010</span> dispone: <span class=\"ref-concepto\">\"que deberá documentarse y estar a disposición de las autoridades competentes\"</span>. El análisis específico debe documentarse y estar a disposición de las autoridades competentes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2064","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Extradición. El Estado Parte en cuyo territorio se encuentre un presunto delincuente, si no lo extradita por el solo hecho de ser uno de sus nacionales, estará obligado, previa solicitud del Estado Parte que pide la extradición, a:","o":["ponerlo a disposición de la autoridad judicial para que decida sobre su entrega, sin perjuicio de lo dispuesto en otras disposiciones.","someter el caso sin demora injustificada a sus autoridades competentes a efectos de enjuiciamiento.","ejecutar en su territorio la pena impuesta por el Estado Parte requirente.","comunicar la negativa al Secretario General de las Naciones Unidas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">someter el caso sin demora injustificada a sus autoridades competentes a efectos de enjuiciamiento</mark></span>El <span class=\"ref-norma\">art. 16.10 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"estará obligado, previa solicitud del Estado Parte que pide la extradición, a someter el caso sin demora injustificada a sus autoridades competentes a efectos de enjuiciamiento\"</span>. Es el principio «extraditar o juzgar»: debe someter el caso a sus autoridades sin demora injustificada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2101","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Extradición. Cuando el derecho interno de un Estado Parte le permita conceder la entrega de uno de sus nacionales sólo a condición de que esa persona sea devuelta para cumplir la condena que le haya sido impuesta, y ambos Estados acepten esa opción, esa extradición o entrega condicional será suficiente para:","o":["que quede cumplida la obligación de someter el caso a sus autoridades a efectos de enjuiciamiento.","que quede cumplida la obligación de ejecutar la condena en el Estado requerido, en los términos que establezca la propia norma.","que se entienda concedida la extradición definitiva del nacional.","que se dispense al Estado requirente de la obligación de aportar pruebas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">que quede cumplida la obligación de someter el caso a sus autoridades a efectos de enjuiciamiento</mark></span>El <span class=\"ref-norma\">art. 16.11 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"esa extradición o entrega condicional será suficiente para que quede cumplida la obligación enunciada en el párrafo 10 del presente artículo\"</span>. La entrega condicional satisface la obligación de enjuiciar del Estado que no extradita a sus nacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-112","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Extradición. Si la extradición solicitada con el propósito de que se cumpla una condena es denegada por el hecho de que la persona buscada es nacional del Estado Parte requerido, éste, si su derecho interno lo permite y de conformidad con sus requisitos:","o":["Estará obligado a hacer cumplir la condena impuesta con arreglo a su propio derecho interno, sin necesidad de solicitud previa del Estado Parte requirente ni de ningún otro requisito adicional.","Entregará a la persona buscada a la Corte Penal Internacional para que cumpla allí la condena impuesta, previa comunicación al Secretario General de las Naciones Unidas.","Considerará, previa solicitud del Estado Parte requirente, la posibilidad de hacer cumplir la condena impuesta o el resto pendiente con arreglo al derecho interno del Estado requirente.","Considerará, previa solicitud del Estado Parte requirente, la posibilidad de juzgar de nuevo a la persona por los mismos hechos con arreglo a su propio derecho interno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Considerará, previa solicitud del Estado Parte requirente, la posibilidad de hacer cumplir la condena impuesta o el resto pendiente con arreglo al derecho interno del Estado requirente</mark></span>Según el <span class=\"ref-norma\">art. 16.12 de la Convención de Palermo</span>: <span class=\"ref-concepto\">\"considerará, previa solicitud del Estado Parte requirente, la posibilidad de hacer cumplir la condena impuesta o el resto pendiente de dicha condena con arreglo al derecho interno del Estado Parte requirente\"</span>. Si se deniega la extradición de un nacional para cumplir condena, el Estado requerido considera hacerla cumplir él mismo. <i>(marca EXOF del temario)</i>"},{"i":"2-ia-2057","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Extradición. El artículo sobre extradición se aplicará a los delitos comprendidos en la Convención o a aquellos que entrañen la participación de un grupo delictivo organizado, siempre y cuando el delito por el que se pide la extradición sea punible:","o":["con arreglo al derecho interno del Estado Parte requirente y del Estado Parte requerido.","con arreglo al derecho interno del Estado Parte requerido exclusivamente.","con una privación de libertad máxima de al menos cuatro años en ambos Estados, en los términos que establezca la propia norma.","con arreglo a los tratados de extradición vigentes entre los Estados Parte."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">con arreglo al derecho interno del Estado Parte requirente y del Estado Parte requerido</mark></span>El <span class=\"ref-norma\">art. 16.1 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"siempre y cuando el delito por el que se pide la extradición sea punible con arreglo al derecho interno del Estado Parte requirente y del Estado Parte requerido\"</span>. Se exige doble incriminación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2102","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Extradición. Si la extradición solicitada con el propósito de que se cumpla una condena es denegada por el hecho de que la persona buscada es nacional del Estado Parte requerido, éste, si su derecho interno lo permite, considerará, previa solicitud del Estado requirente:","o":["la posibilidad de someter a nuevo juicio a la persona por los mismos hechos ante sus propios tribunales, salvo que se disponga otra cosa en la normativa aplicable.","la obligación de entregar a la persona a un tercer Estado para el cumplimiento de la condena.","la posibilidad de conmutar la condena por otra pena prevista en su derecho interno.","la posibilidad de hacer cumplir la condena o el resto pendiente con arreglo al derecho del Estado requirente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la posibilidad de hacer cumplir la condena o el resto pendiente con arreglo al derecho del Estado requirente</mark></span>El <span class=\"ref-norma\">art. 16.12 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"considerará, previa solicitud del Estado Parte requirente, la posibilidad de hacer cumplir la condena impuesta o el resto pendiente de dicha condena con arreglo al derecho interno del Estado Parte requirente\"</span>. Es la ejecución en el Estado requerido de la condena impuesta por el requirente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-179","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Extradición. Nada de lo dispuesto en la Convención se interpretará como imposición de una obligación de extraditar si el Estado Parte requerido tiene motivos justificados para presumir que la solicitud se ha presentado con el fin de perseguir o castigar a una persona por razón de:","o":["Su sexo, raza, religión, nacionalidad, origen étnico u opiniones políticas.","Su sexo, raza, religión, nacionalidad o condición social, pero no por sus opiniones políticas.","Su raza, religión o nacionalidad, siendo irrelevantes su sexo y su origen étnico.","Su orientación sexual, estado civil, profesión o situación económica."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Su sexo, raza, religión, nacionalidad, origen étnico u opiniones políticas</mark></span>Según el <span class=\"ref-norma\">art. 16.14 de la Convención de Palermo</span>: <span class=\"ref-concepto\">\"por razón de su sexo, raza, religión, nacionalidad, origen étnico u opiniones políticas\"</span>. Es la cláusula de no discriminación en la extradición. <i>(marca EXOF del temario)</i>"},{"i":"2-ia-2104","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Extradición. Nada de lo dispuesto en la Convención podrá interpretarse como la imposición de una obligación de extraditar si el Estado Parte requerido tiene motivos justificados para presumir que la solicitud se ha presentado con el fin de perseguir o castigar a una persona por razón de su:","o":["raza, religión, nacionalidad, origen étnico u opiniones políticas.","sexo, raza, religión, nacionalidad, origen étnico u opiniones políticas.","sexo, raza, religión, nacionalidad, orientación sexual u opiniones políticas.","sexo, raza, lengua, nacionalidad, origen social u opiniones políticas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sexo, raza, religión, nacionalidad, origen étnico u opiniones políticas</mark></span>El <span class=\"ref-norma\">art. 16.14 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"por razón de su sexo, raza, religión, nacionalidad, origen étnico u opiniones políticas\"</span>. La cláusula de no discriminación incluye el sexo, a diferencia de otros convenios del tema. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2058","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Extradición. Cuando la solicitud de extradición se base en varios delitos graves distintos, algunos de los cuales no estén comprendidos en el ámbito del artículo, el Estado Parte requerido:","o":["deberá denegar la extradición respecto de estos últimos delitos.","deberá aplicar el artículo a todos los delitos si uno de ellos está comprendido.","podrá condicionar la extradición a que el Estado requirente renuncie a ellos.","podrá aplicar el artículo también respecto de estos últimos delitos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">podrá aplicar el artículo también respecto de estos últimos delitos</mark></span>El <span class=\"ref-norma\">art. 16.2 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"el Estado Parte requerido podrá aplicar el presente artículo también respecto de estos últimos delitos\"</span>. Es una facultad del Estado requerido. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2059","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Extradición. Cada uno de los delitos a los que se aplica el artículo sobre extradición se considerará incluido entre los delitos que dan lugar a extradición en todo tratado de extradición vigente entre los Estados Parte. Los Estados Parte se comprometen a:","o":["revisar los tratados de extradición vigentes para incluir tales delitos en el plazo de un año.","comunicar al Secretario General de las Naciones Unidas los tratados que incluyan tales delitos, conforme al procedimiento que se establezca reglamentariamente.","incluir tales delitos como casos de extradición en todo tratado de extradición que celebren entre sí.","aplicar directamente la Convención como tratado de extradición entre todos ellos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">incluir tales delitos como casos de extradición en todo tratado de extradición que celebren entre sí</mark></span>El <span class=\"ref-norma\">art. 16.3 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"Los Estados Parte se comprometen a incluir tales delitos como casos de extradición en todo tratado de extradición que celebren entre sí\"</span>. Se incluyen de pleno derecho en los tratados vigentes y se comprometen a incluirlos en los futuros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2060","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Extradición. Si un Estado Parte que supedita la extradición a la existencia de un tratado recibe una solicitud de otro Estado Parte con el que no lo vincula ningún tratado de extradición, podrá considerar la Convención:","o":["como un tratado de extradición bilateral con el Estado Parte requirente.","como la base jurídica de la extradición respecto de los delitos a los que se aplica el artículo.","como un criterio interpretativo de su derecho interno en materia de extradición, sin perjuicio de lo dispuesto en otras disposiciones.","como una recomendación para la celebración de un tratado de extradición."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">como la base jurídica de la extradición respecto de los delitos a los que se aplica el artículo</mark></span>El <span class=\"ref-norma\">art. 16.4 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"podrá considerar la presente Convención como la base jurídica de la extradición respecto de los delitos a los que se aplica el presente artículo\"</span>. Es una facultad (podrá), no una obligación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2105","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Extradición. Los Estados Parte no podrán denegar una solicitud de extradición únicamente porque se considere que el delito también entraña:","o":["cuestiones tributarias.","cuestiones políticas.","cuestiones militares.","cuestiones de orden público."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cuestiones tributarias</mark></span>El <span class=\"ref-norma\">art. 16.15 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"Los Estados Parte no podrán denegar una solicitud de extradición únicamente porque se considere que el delito también entraña cuestiones tributarias\"</span>. La naturaleza fiscal del delito no es motivo de denegación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2062","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Extradición. La extradición estará sujeta a las condiciones previstas en el derecho interno del Estado Parte requerido o en los tratados de extradición aplicables, incluidas, entre otras, las relativas al requisito de una pena mínima para la extradición y a:","o":["los plazos máximos de detención de la persona cuya extradición se solicita, salvo que se disponga otra cosa en la normativa aplicable.","las garantías procesales que ha de ofrecer el Estado Parte requirente.","los medios de prueba que ha de aportar el Estado Parte requirente.","los motivos por los que el Estado Parte requerido puede denegar la extradición."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los motivos por los que el Estado Parte requerido puede denegar la extradición</mark></span>El <span class=\"ref-norma\">art. 16.7 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"incluidas, entre otras, las relativas al requisito de una pena mínima para la extradición y a los motivos por los que el Estado Parte requerido puede denegar la extradición\"</span>. Rige el derecho interno del requerido o el tratado aplicable, incluidos los motivos de denegación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-78","p":"Convenio de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Extradición. Señale la correcta:","o":["Los Estados Partes no podrán denegar una solicitud de extradición únicamente porque se considere que el delito también entraña cuestiones tributarias.","Antes de denegar la extradición, el Estado Parte requerido, cuando proceda, consultará al Estado Parte requirente para darle amplia oportunidad de presentar sus opiniones y de proporcionar información pertinente a su alegato.","Los Estados Parte procurarán celebrar acuerdos o arreglos bilaterales y multilaterales para llevar a cabo o aumentar la eficacia de su extradición.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">TODAS SON CORRECTAS.</mark></span><span class=\"ref-norma\">Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, art. 16</span> dispone: <span class=\"ref-concepto\">\"Los Estados Parte no podrán denegar una solicitud de extradición únicamente porque se considere que el delito también entraña cuestiones tributarias\"</span>. El artículo añade que se consultará al Estado requirente antes de denegar y que los Estados procurarán celebrar acuerdos de extradición; por eso son correctas las tres."},{"i":"2-ia-2061","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Extradición. Los Estados Parte que supediten la extradición a la existencia de un tratado deberán, en el momento de depositar su instrumento, informar al Secretario General de las Naciones Unidas de si considerarán o no la Convención:","o":["como la base jurídica de la cooperación en materia de extradición en sus relaciones con otros Estados Parte.","como un tratado de extradición aplicable a todos los delitos graves en sus relaciones con terceros Estados, en los términos que establezca la propia norma.","como una norma de interpretación de los tratados de extradición que hayan celebrado.","como la base jurídica de la asistencia judicial recíproca en sus relaciones con otros Estados Parte."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">como la base jurídica de la cooperación en materia de extradición en sus relaciones con otros Estados Parte</mark></span>El <span class=\"ref-norma\">art. 16.5 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"informar al Secretario General de las Naciones Unidas de si considerarán o no la presente Convención como la base jurídica de la cooperación en materia de extradición en sus relaciones con otros Estados Parte en la presente Convención\"</span>. Deben informar al Secretario General si la consideran base jurídica de la extradición. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2106","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Extradición. Antes de denegar la extradición, el Estado Parte requerido, cuando proceda:","o":["notificará la decisión al Secretario General de las Naciones Unidas para su conocimiento.","solicitará informe a la autoridad judicial competente sobre la procedencia de la extradición, salvo que se disponga otra cosa en la normativa aplicable.","ofrecerá al Estado requirente la posibilidad de juzgar a la persona en su territorio.","consultará al Estado Parte requirente para darle amplia oportunidad de presentar sus opiniones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">consultará al Estado Parte requirente para darle amplia oportunidad de presentar sus opiniones</mark></span>El <span class=\"ref-norma\">art. 16.16 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"consultará al Estado Parte requirente para darle amplia oportunidad de presentar sus opiniones y de proporcionar información pertinente a su alegato\"</span>. Debe consultar previamente al Estado requirente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-7","p":"Convenio de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Extradición. Señale la correcta:","o":["Los Estados Partes podrán denegar una solicitud de extradición únicamente porque se considere que el delito también entraña cuestiones tributarias.","Tras denegar la extradición, el Estado Parte requerido, cuando proceda, consultará al Estado Parte requirente para darle amplia oportunidad de presentar sus opiniones y de proporcionar información pertinente a su aleg1ato.","Los Estados Parte procurarán celebrar acuerdos o arreglos bilaterales y multilaterales para llevar a cabo o aumentar la eficacia de su extradicción.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los Estados Parte procurarán celebrar acuerdos o arreglos bilaterales y multilaterales para llevar a cabo o aumentar la eficacia de su extradicción</mark></span>La A es falsa (dice «podrán denegar»; el texto dice NO podrán) y la B también («tras denegar»; el texto dice ANTES de denegar). Solo la C es correcta. Según el <span class=\"ref-norma\">art. 16.15, 16.16 y 16.17 de la Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional</span>: <span class=\"ref-concepto\">\"15. Los Estados Parte no podrán denegar una solicitud de extradición únicamente porque se considere que el delito también entraña cuestiones tributarias. 16. Antes de denegar la extradición, el Estado Parte requerido... consultará al Estado Parte requirente... 17. Los Estados Parte procurarán celebrar acuerdos o arreglos bilaterales y multilaterales para llevar a cabo la extradición o aumentar su eficacia.\"</span> (verificado con el texto del temario)."}]},{"a":"Artículos 31 y 33 — Prevención (evaluación de instrumentos) y Secretaría ✱ R28 R29","q":[{"i":"2-ia-2207","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Prevención. Los Estados Parte procurarán evaluar periódicamente los instrumentos jurídicos y las prácticas administrativas pertinentes vigentes a fin de detectar:","o":["si resultan eficaces para prevenir y combatir la delincuencia organizada transnacional.","si respetan los derechos humanos de las personas investigadas por delitos de la Convención.","si existe el peligro de que sean utilizados indebidamente por grupos delictivos organizados.","si son compatibles con las obligaciones de cooperación internacional asumidas por el Estado, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">si existe el peligro de que sean utilizados indebidamente por grupos delictivos organizados</mark></span>El <span class=\"ref-norma\">art. 31.4 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"a fin de detectar si existe el peligro de que sean utilizados indebidamente por grupos delictivos organizados\"</span>. La evaluación periódica busca detectar el riesgo de utilización indebida por grupos delictivos organizados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2149","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional, hecha en Nueva York el 15 de noviembre de 2000. Medidas para intensificar la cooperación con las autoridades encargadas de hacer cumplir la ley. Cada Estado Parte adoptará medidas apropiadas para alentar a las personas que participen o hayan participado en grupos delictivos organizados a proporcionar información útil a las autoridades competentes y a prestar ayuda efectiva y concreta que pueda contribuir a:","o":["privar a los grupos delictivos organizados de sus recursos o del producto del delito.","identificar a los miembros de los grupos delictivos organizados y a sus colaboradores.","desmantelar la estructura y las redes internacionales de los grupos delictivos organizados.","proteger a las víctimas y a los testigos de los grupos delictivos organizados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">privar a los grupos delictivos organizados de sus recursos o del producto del delito</mark></span>El <span class=\"ref-norma\">art. 26.1 de la Convención de Palermo</span> dispone: <span class=\"ref-concepto\">\"Prestar ayuda efectiva y concreta a las autoridades competentes que pueda contribuir a privar a los grupos delictivos organizados de sus recursos o del producto del delito\"</span>. La ayuda efectiva y concreta busca privar a los grupos de sus recursos o del producto del delito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-144","p":"Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Secretaría. El Secretario General de las Naciones Unidas prestará los servicios de secretaría necesarios a:","o":["La Oficina de las Naciones Unidas contra la Droga y el Delito.","Los Estados Parte que lo soliciten.","La Conferencia de las Partes en la Convención.","El Consejo de Seguridad de las Naciones Unidas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Conferencia de las Partes en la Convención</mark></span>Según el <span class=\"ref-norma\">art. 33.1 de la Convención de Palermo</span>: <span class=\"ref-concepto\">\"la Conferencia de las Partes en la Convención\"</span>. Ficha RECUERDA R29. <i>(ficha RECUERDA R29 del temario)</i>"}]},{"a":"Artículos 7 y 8 — Tráfico ilícito de migrantes por mar ✱ R36 R37","q":[{"i":"2-151","p":"Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire. Cooperación. Los Estados Parte cooperarán en la mayor medida posible para prevenir y reprimir el tráfico ilícito de migrantes por mar, de conformidad con:","o":["El derecho interno del Estado del pabellón.","La Convención sobre el Estatuto de los Refugiados.","Los acuerdos bilaterales que celebren entre ellos.","El derecho internacional del mar."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El derecho internacional del mar</mark></span>Según el <span class=\"ref-norma\">art. 7 del Protocolo contra el tráfico ilícito de migrantes</span>: <span class=\"ref-concepto\">\"el derecho internacional del mar\"</span>. Ficha RECUERDA R36. <i>(ficha RECUERDA R36 del temario)</i>"},{"i":"2-ia-2336","p":"Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire, que complementa la Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Cooperación. Los Estados Parte cooperarán en la mayor medida posible para prevenir y reprimir el tráfico ilícito de migrantes por mar, de conformidad con:","o":["el derecho internacional humanitario.","el derecho internacional del mar.","las normas de la Convención.","los acuerdos bilaterales de cooperación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el derecho internacional del mar</mark></span>El <span class=\"ref-norma\">art. 7 de el Protocolo contra el tráfico ilícito de migrantes</span> dispone: <span class=\"ref-concepto\">\"cooperarán en la mayor medida posible para prevenir y reprimir el tráfico ilícito de migrantes por mar, de conformidad con el derecho internacional del mar\"</span>. La cooperación marítima se rige por el derecho internacional del mar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2338","p":"Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire, que complementa la Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Medidas contra el tráfico ilícito de migrantes por mar. Todo Estado Parte que sospeche que un buque que haga uso de la libertad de navegación y enarbole el pabellón de otro Estado Parte está involucrado en el tráfico ilícito de migrantes por mar podrá notificarlo al Estado del pabellón, pedirle que confirme la matrícula y, si la confirma:","o":["adoptar de inmediato las medidas apropiadas con respecto a ese buque y comunicarlo después.","solicitarle que adopte él mismo las medidas apropiadas con respecto a ese buque.","solicitarle que designe una autoridad que dirija conjuntamente las medidas con respecto al buque.","solicitarle autorización para adoptar medidas apropiadas con respecto a ese buque."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">solicitarle autorización para adoptar medidas apropiadas con respecto a ese buque</mark></span>El <span class=\"ref-norma\">art. 8.2 de el Protocolo contra el tráfico ilícito de migrantes</span> dispone: <span class=\"ref-concepto\">\"podrá notificarlo al Estado del pabellón, pedirle que confirme la matrícula y, si la confirma, solicitarle autorización para adoptar medidas apropiadas con respecto a ese buque\"</span>. Debe pedir autorización al Estado del pabellón. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2340","p":"Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire, que complementa la Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Medidas contra el tráfico ilícito de migrantes por mar. Todo Estado Parte que haya adoptado medidas con respecto a un buque de otro Estado informará con prontitud al Estado del pabellón de los resultados de dichas medidas, y los Estados Parte responderán con celeridad a toda solicitud de otro Estado Parte para:","o":["confirmar la identidad del armador y de los miembros de la tripulación del buque, sin perjuicio de lo dispuesto en otras disposiciones.","determinar si un buque matriculado en su registro o que enarbola su pabellón está autorizado a hacerlo.","facilitar el acceso a los registros de buques matriculados en su territorio.","autorizar el apresamiento de los buques que se dediquen al tráfico de migrantes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">determinar si un buque matriculado en su registro o que enarbola su pabellón está autorizado a hacerlo</mark></span>El <span class=\"ref-norma\">art. 8.3 y 8.4 de el Protocolo contra el tráfico ilícito de migrantes</span> dispone: <span class=\"ref-concepto\">\"con miras a determinar si un buque que está matriculado en su registro o enarbola su pabellón está autorizado a hacerlo\"</span>. Se responde con celeridad a las solicitudes de verificación de matrícula y de autorización. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-152","p":"Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire. Medidas contra el tráfico ilícito de migrantes por mar. Todo Estado Parte que tenga motivos razonables para sospechar que un buque está involucrado en el tráfico ilícito de migrantes por mar y no posee nacionalidad o se hace pasar por un buque sin nacionalidad podrá:","o":["Apresar el buque y detener a su tripulación.","Hundir el buque una vez evacuadas las personas.","Visitar y registrar el buque.","Escoltar el buque hasta el puerto más cercano."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Visitar y registrar el buque</mark></span>Según el <span class=\"ref-norma\">art. 8.7 del Protocolo contra el tráfico ilícito de migrantes</span>: <span class=\"ref-concepto\">\"visitar y registrar el buque\"</span>. Ficha RECUERDA R37. <i>(ficha RECUERDA R37 del temario)</i>"},{"i":"2-18","p":"Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire que complementa la convención de las Naciones Unidas contra la delincuencia organizada transnacional. Medidas contra el tráfico ilícito de migrantes por mar. Todo Estado Parte que tenga motivos razonables para sospechar que un buque que está haciendo uso de la libertad de navegación con arreglo al derecho internacional y que enarbola el pabellón o tiene matrícula de otro Estado Parte está involucrado en el tráfico ilícito de migrantes por mar podrá notificarlo al Estado del pabellón, pedirle que confirme la matrícula y, si la confirma, solicitarle autorización para adoptar medidas apropiadas con respecto a ese buque. El Estado del pabellón podrá autorizar al Estado requirente, entre otras cosas, a:4","o":["Visitar el buque.5","Registrar el buque.6","Si se hallen pruebas de que el buque está involucrado en el tráfico ilícito de migrantes por mar, adoptar medidas apropiadas con respecto al buque, así como a las personas y la carga que se encuentren a bordo, conforme le haya autorizado el Estado del pabellón.","Todas las opciones son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones son correctas.</mark></span><span class=\"ref-norma\">Art. 8.2 · Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire</span>. La respuesta correcta es la D porque el artículo 8.2 del Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire dispone que el Estado del pabellón podrá autorizar al Estado requirente a visitar el buque, a registrarlo y, si se hallan pruebas de que está involucrado en el tráfico ilícito de migrantes por mar, a adoptar medidas apropiadas con respecto al buque, las personas y la carga a bordo, conforme le haya autorizado el Estado del pabellón. Las tres actuaciones figuran expresamente recogidas en el precepto."},{"i":"2-87","p":"Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire que complementa la convención de las Naciones Unidas contra la delincuencia organizada transnacional. Medidas contra el tráfico ilícito de migrantes por mar. Todo Estado Parte que tenga motivos razonables para sospechar que un buque que está haciendo uso de la libertad de navegación con arreglo al derecho internacional y que enarbola el pabellón o tiene matrícula de otro Estado Parte está involucrado en el tráfico ilícito de migrantes por mar podrá notificarlo al Estado del pabellón, pedirle que confirme la matrícula y, si la confirma, solicitarle autorización para adoptar medidas apropiadas con respecto a ese buque. El Estado del pabellón podrá autorizar al Estado requirente, entre otras cosas, a:","o":["Visitar el buque.","Registrar el buque.","Si se hallen pruebas de que el buque está involucrado en el tráfico ilícito de migrantes por mar, adoptar medidas apropiadas con respecto al buque, así como a las personas y la carga que se encuentren a bordo, conforme le haya autorizado el Estado del pabellón.","Todas las opciones son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">TODAS LAS OPCIONES SON CORRECTAS.</mark></span><span class=\"ref-norma\">Art. 8.2 · Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire</span>. El art. 8.2 del Protocolo enumera que el Estado del pabellón podrá autorizar al Estado requirente a visitar el buque, registrarlo y, si se hallan pruebas, adoptar medidas apropiadas respecto al buque, personas y carga a bordo."},{"i":"2-ia-2339","p":"Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire, que complementa la Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Medidas contra el tráfico ilícito de migrantes por mar. El Estado del pabellón podrá autorizar al Estado requirente, entre otras cosas, a visitar el buque, registrarlo y, si se hallan pruebas de que está involucrado en el tráfico ilícito de migrantes por mar:","o":["detener el buque y conducirlo al puerto más próximo del Estado requirente, con su tripulación.","proceder al embargo del buque y de la carga, y a la detención de la tripulación y los pasajeros, conforme al procedimiento que se establezca reglamentariamente.","adoptar medidas apropiadas con respecto al buque, así como a las personas y a la carga que se encuentren a bordo, conforme le haya autorizado.","ordenar el desvío del buque hacia el puerto del Estado del pabellón con las personas a bordo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">adoptar medidas apropiadas con respecto al buque, así como a las personas y a la carga que se encuentren a bordo, conforme le haya autorizado</mark></span>El <span class=\"ref-norma\">art. 8.2 de el Protocolo contra el tráfico ilícito de migrantes</span> dispone: <span class=\"ref-concepto\">\"si se hallan pruebas de que el buque está involucrado en el tráfico ilícito de migrantes por mar, adoptar medidas apropiadas con respecto al buque, así como a las personas y a la carga que se encuentren a bordo, conforme le haya autorizado el Estado del pabellón\"</span>. Las medidas apropiadas se limitan a las autorizadas por el Estado del pabellón. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2343","p":"Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire, que complementa la Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Medidas contra el tráfico ilícito de migrantes por mar. Todo Estado Parte que tenga motivos razonables para sospechar que un buque está involucrado en el tráfico ilícito de migrantes por mar y no posee nacionalidad o se hace pasar por un buque sin nacionalidad:","o":["podrá visitar el buque, previa autorización de la Organización Marítima Internacional, y adoptar medidas apropiadas, conforme al procedimiento que se establezca reglamentariamente.","deberá notificarlo a los demás Estados Parte y solicitar su autorización para visitar y registrar el buque.","podrá visitar y registrar el buque y, si se hallan pruebas que confirmen la sospecha, adoptará medidas apropiadas de conformidad con el derecho interno e internacional.","podrá visitar y registrar el buque y retenerlo en puerto hasta que se identifique su nacionalidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">podrá visitar y registrar el buque y, si se hallan pruebas que confirmen la sospecha, adoptará medidas apropiadas de conformidad con el derecho interno e internacional</mark></span>El <span class=\"ref-norma\">art. 8.7 de el Protocolo contra el tráfico ilícito de migrantes</span> dispone: <span class=\"ref-concepto\">\"podrá visitar y registrar el buque. Si se hallan pruebas que confirmen la sospecha, ese Estado Parte adoptará medidas apropiadas de conformidad con el derecho interno e internacional, según proceda\"</span>. En el caso de buques sin nacionalidad no hace falta autorización del Estado del pabellón. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2337","p":"Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire, que complementa la Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Medidas contra el tráfico ilícito de migrantes por mar. Todo Estado Parte que tenga motivos razonables para sospechar que un buque que enarbole su pabellón o pretenda estar matriculado en su registro, que carezca de nacionalidad o que tenga en realidad su nacionalidad está involucrado en el tráfico ilícito de migrantes por mar podrá:","o":["solicitar la asistencia de otros Estados Parte a fin de poner término a la utilización del buque para ese fin.","solicitar autorización del Estado del pabellón para visitar y registrar el buque en alta mar.","adoptar medidas de intervención sobre el buque, previa notificación a los demás Estados Parte, en los términos que establezca la propia norma.","notificarlo a la Organización Marítima Internacional para que adopte las medidas pertinentes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">solicitar la asistencia de otros Estados Parte a fin de poner término a la utilización del buque para ese fin</mark></span>El <span class=\"ref-norma\">art. 8.1 de el Protocolo contra el tráfico ilícito de migrantes</span> dispone: <span class=\"ref-concepto\">\"podrá solicitar la asistencia de otros Estados Parte a fin de poner término a la utilización del buque para ese fin\"</span>. El Estado del pabellón puede pedir asistencia, que se prestará con los medios de que se disponga. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2341","p":"Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire, que complementa la Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Medidas contra el tráfico ilícito de migrantes por mar. Los Estados Parte no adoptarán otras medidas sin la autorización expresa del Estado del pabellón, salvo las que sean necesarias para eliminar un peligro inminente para la vida de las personas o:","o":["las que se deriven de los acuerdos bilaterales o multilaterales pertinentes.","las que se deriven de las resoluciones de la Organización Marítima Internacional.","las que se deriven de la legislación nacional del Estado del puerto de destino.","las que se deriven de las normas de la Convención de las Naciones Unidas sobre el Derecho del Mar."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las que se deriven de los acuerdos bilaterales o multilaterales pertinentes</mark></span>El <span class=\"ref-norma\">art. 8.5 de el Protocolo contra el tráfico ilícito de migrantes</span> dispone: <span class=\"ref-concepto\">\"salvo las que sean necesarias para eliminar un peligro inminente para la vida de las personas o las que se deriven de los acuerdos bilaterales o multilaterales pertinentes\"</span>. Las excepciones son el peligro inminente para la vida y los acuerdos bilaterales o multilaterales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2342","p":"Protocolo contra el tráfico ilícito de migrantes por tierra, mar y aire, que complementa la Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Medidas contra el tráfico ilícito de migrantes por mar. Cada Estado Parte designará a una o, de ser necesario, a varias autoridades para recibir y atender las solicitudes de asistencia, de confirmación de la matrícula y de autorización. Esa designación será dada a conocer, por conducto del Secretario General, a todos los demás Estados Parte:","o":["dentro de los quince días siguientes a la designación.","dentro de los tres meses siguientes a la designación.","en el momento de depositar el instrumento de ratificación.","dentro del mes siguiente a la designación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dentro del mes siguiente a la designación</mark></span>El <span class=\"ref-norma\">art. 8.6 de el Protocolo contra el tráfico ilícito de migrantes</span> dispone: <span class=\"ref-concepto\">\"del Secretario General, a todos los demás Estados Parte dentro del mes siguiente a la designación\"</span>. La designación se comunica dentro del mes siguiente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"2-ia-2508","p":"Protocolo contra la fabricación y el tráfico ilícitos de armas de fuego, sus piezas y componentes y municiones, que complementa la Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional. Ámbito de aplicación. El Protocolo no se aplicará a las transacciones entre Estados ni a las transferencias estatales cuando la aplicación del Protocolo pudiera perjudicar el derecho de un Estado Parte a adoptar medidas:","o":["en aras de la defensa nacional conforme a los tratados internacionales ratificados.","en aras de la seguridad nacional en consonancia con la Carta de las Naciones Unidas.","en aras de la paz y la seguridad internacionales conforme a las resoluciones del Consejo.","en aras del orden público interno en consonancia con su ordenamiento constitucional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en aras de la seguridad nacional en consonancia con la Carta de las Naciones Unidas</mark></span>El <span class=\"ref-norma\">art. 4.2 de el Protocolo contra el tráfico de armas de fuego</span> dispone: <span class=\"ref-concepto\">\"cuando la aplicación del Protocolo pudiera perjudicar el derecho de un Estado Parte a adoptar medidas en aras de la seguridad nacional en consonancia con la Carta de las Naciones Unidas\"</span>. Se excluyen las transacciones y transferencias estatales que afecten a la seguridad nacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]}];
